function tourSave(){try{localStorage.setItem(TOUR_STORE,JSON.stringify(tourProgress))}catch{}}
function tourEnsureTimer(){if(!db.timer){const s=exam().subjects[0];startFocus(s.id,s.topics[0].id);db.timer.running=false;db.timer.elapsed=60;updateTimer()}}
function tourReviewForm(){const s=exam().subjects[0];sessionForm({sid:s.id,tid:s.topics[0].id,type:'Revisão',review:true})}
function tourPreview(){openGenerator();$('#modal button[type="submit"]').click()}
function tourPractice(){db=defaults();db.theme=tour.original.db.theme;const e=newExam('Prática do tutorial');e.subjects=baseSubjects();e.availability.forEach(a=>a.enabled=true);db.exams=[e];db.activeExam=e.id;const s=e.subjects[0],t=s.topics[0];t.nextReview=today();e.sessions.push({id:id(),created:new Date().toISOString(),date:today(),subjectId:s.id,topicId:t.id,type:'Questões',minutes:30,qty:15,correct:11,notes:'Exemplo temporário: retomar concordância.',board:'',planId:null,source:'tour'});e.cards.push({id:id(),subjectId:s.id,topicId:t.id,front:'Como identificar o sujeito de uma oração?',back:'Encontre o núcleo do sujeito e confira sua relação com o verbo.',due:today(),interval:0,reps:0,suspended:false});e.mistakes.push({id:id(),subjectId:s.id,topicId:t.id,title:'Confundir o sujeito com o termo mais próximo',explanation:'Procure o núcleo do sujeito antes de conferir a concordância.',category:'Conceito',resolved:false,date:today()});e.plans.push({id:id(),date:today(),start:'19:00',end:'19:30',subjectId:s.id,topicId:t.id,status:'planned',type:'Teoria',reason:'Exemplo de planejamento',sessionId:null});e.mockExams.push({id:id(),name:'Simulado de demonstração',date:today(),timeLimit:180,penalty:0,sessionIds:[e.sessions[0].id]});reviewCardId=null;cardAnswer=false;cardMode='review';sessionFilter='';planDate=today();}
function startTour(area='all',resume=false){if(tour)return;if(aiBusy)return toast('Cancele o pedido de IA antes de iniciar o tutorial.');const original={studyState:studyTourCapture(),db:clone(db),undo:undoState,route,focusMode,planDate,sessionFilter,cardMode,reviewCardId,cardAnswer};const keys=area==='all'?Object.keys(tourAreas):[area];if(keys.some(k=>!tourAreas[k]))return;const steps=keys.flatMap(key=>tourAreas[key].steps.map(s=>({...s,area:key,route:key})));const index=resume&&tourProgress.area===area?Math.min(tourProgress.index,steps.length-1):0;tour={active:true,original,steps,index,area};tourPractice();studyTourSetup();closeModal();tourShowStep();}
function endTour(done=false){if(!tour)return;const old=tour;tourProgress={...tourProgress,area:old.area,index:old.index};if(done){const completed=old.area==='all'?Object.keys(tourAreas):[old.area];tourProgress.completed=[...new Set([...tourProgress.completed,...completed])];tourProgress.index=0}tourSave();tour=null;document.body.classList.remove('tour-timer');tourTarget=null;tourLayer?.hidePopover?.();tourLayer?.remove();tourLayer=null;cancelAnimationFrame(tourFrame);tourFrame=0;tourObserved?.disconnect();tourObserved=null;closeModal();db=old.original.db;try{const raw=localStorage.getItem(STORE);if(raw){const next=JSON.parse(raw);validateBackup(next);db=next}}catch{}studyTourRestore(old.original.studyState);undoState=old.original.undo;({focusMode,planDate,sessionFilter,cardMode,reviewCardId,cardAnswer}=old.original);$('#toast').classList.remove('show');go(done?'guia':old.original.route);if(done)toast('Tour concluído. Seus registros reais continuam preservados.');}
function tourShowStep(){if(!tour)return;const s=tour.steps[tour.index],same=route===s.route;if(!s.modal||!same)closeModal();if(!same||!s.modal)go(s.route);if(s.prepare&&!$(s.selector)?.getClientRects().length)s.prepare();s.onEnter?.();tourProgress.area=tour.area;tourProgress.index=tour.index;tourSave();tourRefresh(true);}
function tourMove(delta){if(!tour)return;const next=tour.index+delta;if(next<0)return;if(next>=tour.steps.length){endTour(true);return}tour.index=next;tourShowStep()}
function tourRefresh(announce=false){if(!tour)return;const s=tour.steps[tour.index];if(!tourLayer){tourLayer=document.createElement('div');tourLayer.id='tour-layer';tourLayer.setAttribute('popover','manual');tourLayer.innerHTML='<div class="tour-shade" data-shade="top"></div><div class="tour-shade" data-shade="left"></div><div class="tour-shade" data-shade="right"></div><div class="tour-shade" data-shade="bottom"></div><div class="tour-ring"></div><section class="tour-bubble" role="region" aria-label="Tutorial ao vivo"><div id="tour-copy"></div></section>';document.body.append(tourLayer);tourObserved=new MutationObserver(()=>tourSchedule());tourObserved.observe($('#content'),{childList:true,subtree:true});tourObserved.observe($('#modal'),{childList:true,subtree:true});}
 if(tourLayer.parentElement!==($('#modal').open?$('#modal'):document.body)){tourLayer.hidePopover?.();($('#modal').open?$('#modal'):document.body).append(tourLayer)}
 if(tourLayer.showPopover){if(tourLayer.matches(':popover-open'))tourLayer.hidePopover();tourLayer.showPopover()}else tourLayer.style.display='block';
 tourTarget=$(s.selector);if(!tourTarget||!tourTarget.getClientRects().length)tourTarget=$('#modal').open?$('#modal .dialog-header'):$('#content .page-heading');
 document.body.classList.toggle('tour-timer',s.selector.startsWith('#timer-dock'));const bubble=$('.tour-bubble',tourLayer);if(announce){$('#tour-copy',tourLayer).innerHTML=`<div class="tour-top"><span class="tour-live-label"><i></i>PRÁTICA GUIADA</span>${btn('Sair','tour-exit','','quiet small')}</div><div class="tour-mascot-row">${norbitMascot(s.click?'focus':'welcome','tour')}<div class="tour-count">${esc(tourAreas[s.area].label)} · ${tour.index+1} de ${tour.steps.length}</div></div><h2 id="tour-title" tabindex="-1">${s.title}</h2><p>${s.body}</p><div class="tour-hint">${s.click?'Clique no controle destacado para continuar.':'Experimente o controle ou avance no seu ritmo.'}</div><div class="tour-safe">Dados de demonstração. Seus estudos estão preservados.</div><div class="tour-track"><span style="width:${(tour.index+1)/tour.steps.length*100}%"></span></div><div class="tour-controls">${btn('Anterior','tour-prev',tour.index===0?'disabled':'','quiet small')}${btn(s.click?'Pular passo':tour.index===tour.steps.length-1?'Concluir':'Próximo','tour-next','','primary small')}</div>`;if(!matchMedia('(prefers-reduced-motion: reduce)').matches){bubble.getAnimations().forEach(a=>a.cancel());bubble.animate([{opacity:.25,transform:'translateY(8px) scale(.985)'},{opacity:1,transform:'translateY(0) scale(1)'}],{duration:240,easing:'cubic-bezier(.2,.8,.2,1)'})}$('#tour-title',tourLayer).focus({preventScroll:true});tourTarget.scrollIntoView({block:'center',inline:'nearest',behavior:'instant'});}
 tourPosition();
}
let tourGeometry=null,tourVelocity=[0,0,0,0],tourGoal=null,tourLast=0;
function tourPosition(){if(!tour||!tourTarget||!tourLayer)return;const rect=tourTarget.getBoundingClientRect(),w=innerWidth,h=innerHeight,p=6;const x=Math.max(8,Math.min(w-16,rect.left-p)),y=Math.max(8,Math.min(h-16,rect.top-p)),right=Math.max(x+1,Math.min(w-8,rect.right+p)),bottom=Math.max(y+1,Math.min(h-8,rect.bottom+p));tourGoal=[x,y,right-x,bottom-y];if(!tourGeometry||matchMedia('(prefers-reduced-motion: reduce)').matches){tourGeometry=[...tourGoal];tourVelocity=[0,0,0,0]}const shades=$$('.tour-shade',tourLayer);const boxes=[[0,0,w,y],[0,y,x,bottom-y],[right,y,w-right,bottom-y],[0,bottom,w,h-bottom]];boxes.forEach(([left,top,width,height],i)=>Object.assign(shades[i].style,{left:left+'px',top:top+'px',width:width+'px',height:height+'px'}));const bubble=$('.tour-bubble',tourLayer),bw=Math.min(360,w-24);bubble.style.width=bw+'px';const bh=bubble.offsetHeight;let bx=Math.max(12,Math.min(w-bw-12,right+16)),by=Math.max(12,Math.min(h-bh-12,y));if(w<700){bx=12;by=h-bh-12; if(bottom>by-12&&y<by+bh){const scroller=tourTarget.closest('dialog')||window;scroller.scrollBy({top:rect.top-85,behavior:'instant'});const r=tourTarget.getBoundingClientRect();if(Math.abs(r.top-rect.top)>1){tourSchedule();return}}}else if(right+bw+28>w){bx=Math.max(12,Math.min(w-bw-12,x));by=bottom+16;if(by+bh>h-12)by=Math.max(12,y-bh-16)}Object.assign(bubble.style,{left:bx+'px',top:by+'px'});if(!tourFrame){tourLast=performance.now();tourFrame=requestAnimationFrame(tourSpring)};}
function tourSpring(now){tourFrame=0;if(!tourLayer||!tourGoal)return;const dt=Math.min(.032,(now-tourLast)/1000);tourLast=now;let moving=false;for(let i=0;i<4;i++){const d=tourGoal[i]-tourGeometry[i];tourVelocity[i]+=(d*340-tourVelocity[i]*37)*dt;tourGeometry[i]+=tourVelocity[i]*dt;if(Math.abs(d)>.4||Math.abs(tourVelocity[i])>.4)moving=true}const [x,y,w,h]=tourGeometry;Object.assign($('.tour-ring',tourLayer).style,{transform:`translate3d(${x}px,${y}px,0)`,width:w+'px',height:h+'px'});if(moving)tourFrame=requestAnimationFrame(tourSpring)}
let tourScheduled=false;
function tourSchedule(){if(!tour||tourScheduled)return;tourScheduled=true;requestAnimationFrame(()=>{tourScheduled=false;if(tour){const s=tour.steps[tour.index];const next=$(s.selector);if(next?.getClientRects().length)tourTarget=next;tourPosition()}})}
window.addEventListener('resize',tourSchedule);document.addEventListener('scroll',tourSchedule,true);
document.addEventListener('click',event=>{if(!tour||event.target.closest('#tour-layer'))return;const s=tour.steps[tour.index],index=tour.index;if(s.observeOnly&&event.target.closest(s.selector)){event.preventDefault();event.stopImmediatePropagation();return}if(s.click&&tourTarget?.contains(event.target)){requestAnimationFrame(()=>{if(!tour||tour.index!==index)return;const ok=s.click==='open'?$('#modal').open:s.click==='preview'?!!$('#modal .preview-list'):s.click==='timer'?!!db.timer:s.click==='flip'?cardAnswer:s.click==='rated'?!cardAnswer:s.click==='saved'?!$('#modal').open:true;if(ok)tourMove(1)})}},true);
