function viewTourHub(){return heading('Aprenda usando o Norte.','Escolha uma área. O tour abre a tela, destaca os controles e acompanha seus cliques.')+`<section class="tour-hub-intro"><div><span class="tag blue">Tutorial ao vivo</span><h2>Você aprende. Seus dados ficam seguros.</h2><p>Pratique nas telas reais com uma preparação temporária. Você pode sair, retomar ou explorar uma área de cada vez.</p><div class="actions">${btn('Tour completo','tour-start','data-area="all"','primary')}${tourProgress.index>0?btn('Retomar tour','tour-resume'):''}</div></div>${norbitMascot('welcome','hero')}</section><div class="tour-area-list">${Object.entries(tourAreas).map(([key,a],i)=>`<button class="tour-area" data-action="tour-start" data-area="${key}"><span class="tour-area-number">${String(i+1).padStart(2,'0')}</span><span><strong>${a.label}</strong><small>${a.caption}</small></span><span class="tour-area-status">${tourProgress.completed.includes(key)?'Concluído · ':''}${a.steps.length} passos <span aria-hidden="true">↗</span></span></button>`).join('')}</div>`}

function guideInvitation(){return tourProgress.completed.length>=Object.keys(tourAreas).length?'':`<aside class="guide-invitation"><div><span class="guide-eyebrow">APRENDA NA PRÁTICA</span><h2>Conheça o Norte por dentro.</h2><p>Um tour que acompanha seus cliques nas próprias telas.</p></div><div class="actions">${btn('Começar tour','tour-start','data-area="all"','primary small')}${btn('Escolher uma área','guide-open','','quiet small')}</div></aside>`}
try{recoveryRaw=localStorage.getItem(STORE+'.recovery');recoveryProtected=!!recoveryRaw;const raw=localStorage.getItem(STORE);if(raw){db=JSON.parse(raw);validateBackup(db)}}catch(e){try{recoveryRaw=localStorage.getItem(STORE)}catch{}recoveryProtected=false;storageProblem='Não foi possível carregar os dados salvos. Baixe os dados originais para recuperação antes de continuar.';db=defaults()}
function exam(){return db.exams.find(e=>e.id===db.activeExam)||null}
function newExam(name='Minha preparação'){return {id:id(),name,date:'',board:'',position:'',dailyMinutes:90,dailyQuestions:20,weeklyMinutes:600,targetAccuracy:80,blockMinutes:30,availability:Array.from({length:7},(_,day)=>({day,enabled:day!==0,start:'19:00',end:'20:30'})),subjects:[],sessions:[],plans:[],cards:[],mistakes:[],resources:[],mockExams:[]}}
function persist(){if(tour?.active)return true;try{if(recoveryRaw&&!recoveryProtected){localStorage.setItem(STORE+'.recovery',recoveryRaw);recoveryProtected=true}localStorage.setItem(STORE,JSON.stringify(db));storageProblem='';return true}catch{storageProblem='O navegador não conseguiu salvar. Exporte um backup agora para preservar seus registros.';return false}}
function commit(message,undo=false){persist();render();if(message)toast(message,undo)}
function toast(message,undo=false){clearTimeout(toastTimeout);const el=$('#toast');el.innerHTML=`<span>${esc(message)}</span>${undo?'<button data-action="undo">Desfazer</button>':''}`;el.classList.add('show');toastTimeout=setTimeout(()=>el.classList.remove('show'),undo?12000:5000)}
function snapshot(){undoState=clone(db)}
function subject(sid,e=exam()){return e?.subjects.find(s=>s.id===sid)}
function topic(sid,tid,e=exam()){return subject(sid,e)?.topics.find(t=>t.id===tid)}
function subjectName(sid){return subject(sid)?.name||'Matéria arquivada'}
function topicName(sid,tid){return topic(sid,tid)?.name||'Estudo geral'}
function allTopics(e=exam()){return e?e.subjects.flatMap(s=>s.topics.map(t=>({s,t}))):[]}
function stats(sessions){const m=sessions.reduce((a,s)=>a+s.minutes,0),q=sessions.reduce((a,s)=>a+s.qty,0),c=sessions.reduce((a,s)=>a+s.correct,0);return {m,q,c,accuracy:q?Math.round(c/q*100):null}}
function periodSessions(days,e=exam()){const start=addDays(today(),1-days);return e?e.sessions.filter(s=>s.date>=start&&s.date<=today()):[]}
function topicStats(sid,tid,days=null){return stats((days?periodSessions(days):exam().sessions).filter(x=>x.subjectId===sid&&(!tid||x.topicId===tid)))}
function lastStudied(sid,tid){return exam().sessions.filter(x=>x.subjectId===sid&&(!tid||x.topicId===tid)&&x.date<=today()).map(x=>x.date).sort().at(-1)}
function topicPriority(s,t){const st=topicStats(s.id,t.id,30),last=lastStudied(s.id,t.id);const smooth=(st.c+5)/(st.q+10);const days=last?Math.min(30,Math.max(0,diffDays(last,today()))):15;const due=t.nextReview&&t.nextReview<=today();return s.weight*3+t.weight*1.5+(1-smooth)*10+days*.22+(t.stage==='new'?3:0)+(due?6:0)-(t.stage==='mastered'?3:0)+studyDeadlinePriority(s.id)}
function recommendations(){return allTopics().filter(x=>!x.s.archived).map(x=>({...x,score:topicPriority(x.s,x.t)})).sort((a,b)=>b.score-a.score)}
function reason(s,t){const deadline=studyTasks().find(x=>x.subjectId===s.id&&diffDays(today(),x.date)<=14);if(deadline)return 'Prazo: '+deadline.title+' · '+dateLabel(deadline.date);const st=topicStats(s.id,t.id,30);if(t.nextReview&&t.nextReview<=today())return 'Revisão pendente';if(st.q>=10&&st.accuracy<exam().targetAccuracy)return `${st.accuracy}% de acerto em ${st.q} questões recentes`;if(t.stage==='new')return 'Tópico ainda não iniciado';const last=lastStudied(s.id,t.id);return last?`${diffDays(last,today())} dias desde o último estudo`:'Construa uma primeira referência de desempenho'}
function dueTopics(){return allTopics().filter(x=>!x.s.archived&&x.t.nextReview&&x.t.nextReview<=today()).sort((a,b)=>a.t.nextReview.localeCompare(b.t.nextReview))}
function dueCards(){return exam().cards.filter(c=>c.due<=today()&&!c.suspended)}
