const btn=(label,action,extra='',kind='secondary')=>`<button class="${kind}" data-action="${action}" ${extra}>${label}</button>`;
const tag=(text,kind='')=>`<span class="tag ${kind}">${esc(text)}</span>`;
const progress=(current,total)=>`<div class="progress" role="progressbar" aria-valuenow="${Math.min(100,Math.round(current/(total||1)*100))}" aria-valuemin="0" aria-valuemax="100"><span style="width:${Math.max(0,Math.min(100,current/(total||1)*100))}%"></span></div>`;
const heading=(title,subtitle,actions='')=>`<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`;
const empty=(title,text,button='')=>`<div class="empty"><div class="empty-mark">+</div><h3>${title}</h3><p>${text}</p>${button}</div>`;
const panelHead=(title,sub='',action='')=>`<div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`;
const metric=(label,value,foot='')=>`<div class="metric"><div class="metric-label">${label}</div><div class="metric-value">${value}</div><div class="metric-foot">${foot}</div></div>`;
function subjectOptions(sel){return exam().subjects.filter(s=>!s.archived||s.id===sel).map(s=>`<option value="${s.id}" ${s.id===sel?'selected':''}>${esc(s.name)}</option>`).join('')}
function topicOptions(sid,sel){return `<option value="">Estudo geral da matéria</option>`+(subject(sid)?.topics||[]).map(t=>`<option value="${t.id}" ${t.id===sel?'selected':''}>${esc(t.name)}</option>`).join('')}
function selection(sid,tid){return `<label>Matéria<select name="subjectId" id="form-subject" required>${subjectOptions(sid)}</select></label><label>Assunto<select name="topicId" id="form-topic">${topicOptions(sid||exam().subjects.find(s=>!s.archived)?.id,tid)}</select></label>`}
function render(){
  document.body.classList.toggle('norbit-active',route==='ia');
  if($('#norbit-launcher'))$('#norbit-launcher').setAttribute('aria-current',route==='ia'?'page':'false');
  document.documentElement.dataset.theme=db.theme;
  $('#avatar').textContent=db.name.trim().charAt(0).toUpperCase()||'E';
  $('#exam-select').innerHTML=db.exams.map(e=>`<option value="${e.id}" ${e.id===db.activeExam?'selected':''}>${esc(e.name)}</option>`).join('')||'<option>Comece sua preparação</option>';
  const due=exam()?dueTopics().length+dueCards().length:0;
  $('#nav').innerHTML=routes.map(([r,label],i)=>`${i===8?'<div class="nav-divider"></div>':''}<a class="nav-item ${route===r?'active':''}" href="#${r}" ${route===r?'aria-current="page"':''}><span class="nav-index">${String(i+1).padStart(2,'0')}</span>${esc(studyLabel(r))}${r==='revisoes'&&due?`<span class="count-badge">${due}</span>`:''}</a>`).join('');
  $('#breadcrumb').textContent='Seu espaço / '+(studyLabel(route)||'Hoje');
  const views={hoje:viewPersonalToday,plano:viewPersonalPlan,edital:viewSyllabus,foco:viewFocus,questoes:viewQuestions,simulados:viewMocks,revisoes:viewReviews,cartoes:viewCards,evolucao:viewAnalytics,biblioteca:viewLibrary,historico:viewHistory,ajustes:viewSettings,guia:viewTourHub,ia:viewAI,prazos:viewDeadlines};
  $('#content').innerHTML=(storageProblem?`<div class="note warn" style="margin-bottom:20px">${esc(storageProblem)} ${btn('Exportar backup','export','','secondary small')}${recoveryRaw?btn('Baixar dados para recuperação','recovery-export','','secondary small'):''}</div>`:'')+(exam()&&route==='hoje'?guideInvitation():'')+(!exam()&&!['ajustes','guia','ia'].includes(route)?viewWelcome():views[route]());
  syncFocusUI();updateTimer();
  $('.local-state').innerHTML=tour?'<span class="state-dot"></span>Prática temporária':'<span class="state-dot"></span>Salvo neste aparelho';
  if(tour)tourSchedule();
}
function syncFocusUI(){if(route!=='foco'||db.timer||!exam())return;$$('[data-action="focus-mode"]').forEach(b=>b.classList.toggle('active',b.dataset.mode===focusMode));if($('#focus-duration')){$('#focus-duration').closest('label').hidden=focusMode==='free';$('#timer-count').textContent=focusMode==='free'?'00:00':$('#focus-duration').value+':00'}}
function viewWelcome(){return heading('Um caminho mais claro.','Organize sua preparação, estude com intenção e acompanhe o que está aprendendo.')+`<section class="panel onboarding norbit-onboarding"><div class="onboarding-mascot">${norbitMascot('welcome','hero')}</div><div class="onboarding-copy"><div class="tag blue">Bem-vindo ao Norte</div><h2>Seu próximo passo começa aqui.</h2><p>Defina seu concurso e transforme o edital em pequenos passos. Você pode começar com uma base de matérias e adaptar tudo depois.</p><div class="actions">${btn('Criar minha preparação','exam-new','','primary')}${btn('Conhecer com dados de exemplo','demo')}${btn('Ver tutorial','guide-open','','quiet')}</div><div class="separation"></div><p style="font-size:.8rem;margin:0">Seus registros ficam neste navegador. Exporte backups para levar os dados a outro aparelho.</p></div></section>`}
function viewToday(){
 const e=exam(),st=stats(e.sessions.filter(s=>s.date===today())),week=stats(periodSessions(7)),recs=recommendations(),next=e.plans.find(p=>p.date===today()&&p.status==='planned'),rec=next?{s:subject(next.subjectId),t:topic(next.subjectId,next.topicId)}:recs[0],dues=dueTopics(),cards=dueCards();
 const title=rec?.t?rec.t.name:studyKinds[studyKind()].syllabus+', seu ponto de partida';
 const topics=allTopics(),covered=topics.filter(x=>['covered','mastered'].includes(x.t.stage)).length,coverage=topics.length?Math.round(covered/topics.length*100):0;
 const days=e.date?diffDays(today(),e.date):null;
 const activity=e.plans.filter(p=>p.date===today()).sort((a,b)=>a.start.localeCompare(b.start));
 return heading(`Seu estudo de hoje.`,`${new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'})} · ${esc(db.name)}${days!==null?` · ${days>=0?days+' dias até '+(studyKind()==='concurso'?'a prova':'a data-alvo'):(studyKind()==='concurso'?'Data da prova passou':'Data-alvo passou')}`:''}`,btn('Planejar semana','navigate','data-route="plano"'))+
 `<div class="metrics">${metric('Tempo de estudo',minutesLabel(st.m),`${Math.round(st.m/(e.dailyMinutes||1)*100)}% da meta de hoje`)}${metric('Questões resolvidas',st.q,`Meta diária: ${e.dailyQuestions}`)}${metric('Acertos de hoje',st.accuracy===null?'Sem dados':st.accuracy+'%',st.q?`${st.c} acertos em ${st.q} questões`:'Registre suas primeiras questões')}${metric('Constância',`${streak()} <span>dias</span>`,'Dias com estudo ou questões')}</div>`+
 `<div class="grid two"><div><section class="hero"><div>${tag(next?'Próximo no seu plano':'Sugestão para começar','blue')}<h2>${esc(title)}</h2><p>${rec?.t?`${esc(rec.s.name)} · ${esc(reason(rec.s,rec.t))}.`:'Adicione os assuntos que você quer estudar para receber sugestões explicadas.'}</p><div class="actions">${rec?.t?btn('Iniciar sessão de foco','start-focus',`data-sid="${rec.s.id}" data-tid="${rec.t.id}" ${next?`data-pid="${next.id}"`:''}`,'primary'):btn(studyKinds[studyKind()].syllabus,'navigate','data-route="edital"','primary')}${btn('Registrar um estudo','session')}</div></div><div class="hero-monogram" aria-hidden="true">n.</div></section>
 <section class="panel">${panelHead('Seu plano de hoje',`${activity.length} atividades planejadas`,btn('Ver semana','navigate','data-route="plano"','quiet small'))}${activity.length?activity.map(planRow).join(''):empty('Ainda sem plano para hoje','Escolha seus horários e gere uma semana possível de cumprir.',btn('Montar planejamento','navigate','data-route="plano"'))}</section>
 <section class="panel subsection">${panelHead('Onde colocar sua atenção','Sugestões baseadas em peso, revisões e desempenho recente')}${recs.slice(0,3).map((x,i)=>`<div class="row"><span class="row-time">0${i+1}</span><div class="row-main"><h3>${esc(x.t.name)}</h3><p>${esc(x.s.name)} · ${esc(reason(x.s,x.t))}</p></div>${btn('Estudar','start-focus',`data-sid="${x.s.id}" data-tid="${x.t.id}"`,'quiet small')}</div>`).join('')||empty('Seus assuntos dão direção','Adicione assuntos para construir uma rotina personalizada.')}</section></div>
 <div class="stack"><section class="panel">${panelHead('Um pouco, todos os dias','Metas que respeitam seu ritmo',btn('Editar','navigate','data-route="ajustes"','quiet small'))}<div class="goal-row"><div class="spread"><span>Estudo hoje</span><strong>${minutesLabel(st.m)} / ${minutesLabel(e.dailyMinutes)}</strong></div>${progress(st.m,e.dailyMinutes)}</div><div class="goal-row"><div class="spread"><span>Questões hoje</span><strong>${st.q} / ${e.dailyQuestions}</strong></div>${progress(st.q,e.dailyQuestions)}</div><div class="goal-row"><div class="spread"><span>Últimos 7 dias</span><strong>${minutesLabel(week.m)} / ${minutesLabel(e.weeklyMinutes)}</strong></div>${progress(week.m,e.weeklyMinutes)}</div></section>
 <section class="panel">${panelHead('Recuperar para lembrar','Revisões e prática de memória')}<div class="row"><div class="row-main"><h3>${dues.length} assuntos para revisar</h3><p>${dues.length?'Retome os assuntos antes de avançar.':'Nenhuma revisão vencida.'}</p></div>${btn('Abrir','navigate','data-route="revisoes"','quiet small')}</div><div class="row"><div class="row-main"><h3>${cards.length} cartões disponíveis</h3><p>Responda antes de revelar a resposta.</p></div>${btn('Praticar','navigate','data-route="cartoes"','quiet small')}</div></section>
 <section class="panel">${panelHead(studyKind()==='concurso'?'Seu edital em movimento':'Seu aprendizado em movimento')}<div class="ring" style="--angle:${coverage*3.6}deg"><div><strong>${coverage}%</strong><small>teoria coberta</small></div></div><p style="text-align:center;font-size:.79rem;margin-top:18px">${covered} de ${topics.length} assuntos com teoria concluída. Cobertura e desempenho são medidas diferentes.</p></section></div></div>`;
}
function planRow(p){return `<div class="row"><button class="check ${p.status==='done'?'done':''}" data-action="plan-complete" data-id="${p.id}" aria-label="${p.status==='done'?'Ver registro concluído':'Registrar conclusão da atividade'}">${p.status==='done'?'✓':''}</button><div class="row-time">${esc(p.start)}<br><small>${esc(p.end)}</small></div><div class="row-main"><h3>${esc(topicName(p.subjectId,p.topicId))}</h3><p>${esc(subjectName(p.subjectId))} · ${p.type==='Revisão'?'Revisão':esc(p.reason||'Estudo planejado')}</p></div><div class="row-right">${p.status==='done'?tag('Concluída','green'):p.status==='skipped'?tag('Adiada','amber'):`<div class="actions">${btn('Foco','start-focus',`data-sid="${p.subjectId}" data-tid="${p.topicId||''}" data-pid="${p.id}"`,'quiet small')}${btn('Editar','plan-edit',`data-id="${p.id}"`,'quiet small')}</div>`}</div></div>`}
function viewPlan(){const e=exam(),start=addDays(planDate,-((weekday(planDate)+6)%7)),week=Array.from({length:7},(_,i)=>addDays(start,i)),items=e.plans.filter(p=>p.date===planDate).sort((a,b)=>a.start.localeCompare(b.start));return heading('Uma semana possível.','Distribua seus estudos nos horários que você realmente tem.',btn('Nova atividade','plan-new')+btn('Gerar plano adaptativo','plan-generate','','primary'))+
 `<div class="filters">${btn('Semana anterior','week-prev','','quiet')}${btn('Hoje','plan-today','','secondary small')}${btn('Próxima semana','week-next','','quiet')}<label style="margin-left:auto">Ir para data<input type="date" id="plan-date" value="${planDate}"></label></div><div class="week-strip">${week.map(d=>{const list=e.plans.filter(p=>p.date===d);return `<button class="day-pill ${d===planDate?'active':''}" data-action="plan-day" data-date="${d}"><span>${new Date(d+'T12:00:00').toLocaleDateString('pt-BR',{weekday:'short'})}</span><strong>${d.slice(-2)}</strong><small>${list.length?list.filter(p=>p.status==='done').length+'/'+list.length:'Livre'}</small></button>`}).join('')}</div>
 <div class="grid two"><section class="panel">${panelHead(dateLabel(planDate,true),`${items.length} atividades · ${minutesLabel(items.reduce((a,p)=>a+Math.max(0,timeMin(p.end)-timeMin(p.start)),0))} planejados`)}${items.length?items.map(planRow).join(''):empty('Espaço para o que importa','Adicione uma atividade ou gere um plano com a sua disponibilidade.',btn('Gerar plano','plan-generate'))}</section><aside class="stack"><section class="panel">${panelHead('Como seu plano é construído')}<div class="insight"><h3>Importância no edital</h3><p>O peso de cada matéria e assunto influencia a distribuição.</p></div><div class="insight"><h3>Aprendizagem recente</h3><p>Acertos dos últimos 30 dias são suavizados para evitar conclusões com poucas questões.</p></div><div class="insight"><h3>Revisões e tempo sem estudar</h3><p>Assuntos com revisão pendente e pouco contato voltam para o plano.</p></div><div class="insight"><h3>Disponibilidade real</h3><p>Os blocos cabem nos seus horários. Atividades já existentes são respeitadas.</p></div></section><div class="note">O plano é uma sugestão ajustável. Ao concluir, registre o tempo real e o resultado do estudo.</div></aside></div>`}
function viewSyllabus(){const e=exam(),topics=allTopics(),covered=topics.filter(x=>['covered','mastered'].includes(x.t.stage)).length;return heading(studyKind()==='concurso'?'Seu edital, em pequenos passos.':'Seu aprendizado, em pequenos passos.',studyKind()==='concurso'?'Personalize matérias, pesos e assuntos. A preparação começa pelo que sua prova exige.':'Organize disciplinas, temas e assuntos. Ajuste a importância de cada um ao seu objetivo.',btn('Adicionar matéria','subject-new','','primary'))+
 `<div class="metrics">${metric('Matérias ativas',e.subjects.filter(s=>!s.archived).length)}${metric('Assuntos',topics.length)}${metric('Teoria concluída',covered,`${topics.length?Math.round(covered/topics.length*100):0}% do edital`)}${metric('Consolidados',topics.filter(x=>x.t.stage==='mastered').length,'Marcados por você')}</div><div class="filters"><input id="topic-search" placeholder="Buscar matéria ou assunto" value="${esc(topicFilter)}" aria-label="Buscar no edital"><select id="topic-status" aria-label="Filtrar etapa"><option value="all">Todas as etapas</option>${stages.map(([v,l])=>`<option value="${v}" ${topicStatus===v?'selected':''}>${l}</option>`).join('')}</select></div>
 <div class="stack" id="syllabus-list">${syllabusList()}</div>`}
function syllabusList(){const e=exam();return e.subjects.map(s=>{const matching=s.topics.filter(t=>(topicStatus==='all'||t.stage===topicStatus)&&(!topicFilter||`${s.name} ${t.name}`.toLowerCase().includes(topicFilter.toLowerCase())));if((topicFilter||topicStatus!=='all')&&!matching.length&&!s.name.toLowerCase().includes(topicFilter.toLowerCase()))return '';const st=topicStats(s.id,null),cov=s.topics.filter(t=>['covered','mastered'].includes(t.stage)).length;return `<section class="panel subject"><div class="subject-head"><div class="subject-line"></div><div class="row-main"><h2>${esc(s.name)} ${s.archived?tag('Arquivada'):''}</h2><p>${s.topics.length} assuntos · peso ${s.weight} · ${cov} concluídos ${st.q?'· '+st.accuracy+'% de acerto':''}</p></div>${btn('Editar','subject-edit',`data-id="${s.id}"`,'quiet small')}${btn('+ Assuntos','topic-new',`data-sid="${s.id}"`,'secondary small')}</div><div class="subject-content">${matching.map(t=>{const st=topicStats(s.id,t.id);return `<div class="topic-row"><div>${esc(t.name)}<small>${t.nextReview?'Próxima revisão: '+dateLabel(t.nextReview):'Sem revisão agendada'}</small></div><select data-stage="${t.id}" data-sid="${s.id}" aria-label="Etapa de ${esc(t.name)}">${stages.map(([v,l])=>`<option value="${v}" ${v===t.stage?'selected':''}>${l}</option>`).join('')}</select><span class="topic-accuracy muted">${st.q?st.accuracy+'% · '+st.q+'q':'Sem questões'}</span>${btn('Detalhes','topic-edit',`data-sid="${s.id}" data-tid="${t.id}"`,'quiet small')}</div>`}).join('')||'<p style="font-size:.83rem;padding:12px 0">Adicione os assuntos do seu edital, um por linha.</p>'}</div></section>`}).join('')||empty('Monte seu mapa de estudos','Crie sua primeira matéria e cole os assuntos do edital.',btn('Adicionar matéria','subject-new'))}
function viewFocus(){const e=exam(),timer=db.timer;return heading('Uma coisa de cada vez.','Escolha um assunto. Feche as distrações. Comece um pequeno bloco de estudo.')+`<div class="grid two"><section class="panel timer-panel"><div class="segmented"><button class="${timer?.mode==='free'?'':'active'}" data-action="focus-mode" data-mode="countdown">Bloco de foco</button><button class="${timer?.mode==='free'?'active':''}" data-action="focus-mode" data-mode="free">Cronômetro livre</button></div><div class="timer-select">${timer?`<h2>${esc(topicName(timer.subjectId,timer.topicId,db.exams.find(e=>e.id===timer.examId)))}</h2><p>${esc(db.exams.find(e=>e.id===timer.examId)?.subjects.find(s=>s.id===timer.subjectId)?.name||'Sessão em andamento')}</p>`:`<label>Matéria<select id="focus-subject">${subjectOptions()}</select></label><label>Assunto<select id="focus-topic">${topicOptions(e.subjects.find(s=>!s.archived)?.id)}</select></label><label>Duração do bloco<select id="focus-duration"><option value="25">25 minutos</option><option value="30" selected>30 minutos</option><option value="45">45 minutos</option><option value="50">50 minutos</option></select></label>`}</div><div class="timer-circle"><div><div class="timer-count" id="timer-count">${timer?'00:00':'30:00'}</div><small id="timer-status">Pronto quando você estiver.</small></div></div><div class="actions">${timer?btn(timer.running?'Pausar':'Continuar','timer-toggle','','primary')+btn('Concluir e registrar','timer-finish')+btn('Descartar','timer-discard','','quiet'):btn('Começar a estudar','timer-start','','primary')}</div><p style="margin-top:22px">O tempo real só entra no histórico depois que você registra a sessão.</p>${timerOptions(timer)}</section><aside class="stack"><section class="panel">${panelHead('Faça o tempo valer')}<div class="insight"><h3>Antes de começar</h3><p>Defina uma tarefa concreta: resolver 15 questões, entender um conceito ou revisar seus erros.</p></div><div class="insight"><h3>Durante o bloco</h3><p>Explique com suas próprias palavras e tente responder sem consultar o material.</p></div><div class="insight"><h3>Ao terminar</h3><p>Registre seu resultado, anote a dificuldade e escolha quando retomar o assunto.</p></div></section><div class="note">Faça pausas entre os blocos. O cronômetro não inicia outra sessão automaticamente.</div></aside></div>`}
function viewQuestions(){const e=exam(),q=stats(e.sessions.filter(s=>s.qty>0)),mistakes=e.mistakes.filter(m=>mistakeFilter==='all'||(mistakeFilter==='open'?!m.resolved:m.resolved));return heading('Aprenda com cada erro.','Registre questões em uma única sessão e transforme dificuldades em prática.',btn('Registrar questões','questions-new','','primary'))+
 `<div class="metrics">${metric('Questões resolvidas',q.q)}${metric('Acerto acumulado',q.accuracy===null?'Sem dados':q.accuracy+'%',`${q.c} acertos`)}${metric('Erros nas questões',q.q-q.c)}${metric('Pendências no caderno',e.mistakes.filter(m=>!m.resolved).length,'Dificuldades registradas por você')}</div><div class="grid two"><section class="panel">${panelHead('Caderno de erros','Registre o motivo e a regra correta',btn('+ Anotar erro','mistake-new','','secondary small'))}<div class="segmented" style="margin-bottom:15px">${[['open','Pendentes'],['resolved','Resolvidos'],['all','Todos']].map(([v,l])=>`<button class="${mistakeFilter===v?'active':''}" data-action="mistake-filter" data-value="${v}">${l}</button>`).join('')}</div>${mistakes.length?mistakes.map(m=>`<div class="insight"><div class="spread"><h3>${esc(m.title)}</h3>${tag(m.resolved?'Resolvido':m.category,m.resolved?'green':'amber')}</div><small>${esc(subjectName(m.subjectId))} · ${esc(topicName(m.subjectId,m.topicId))}</small><p class="detail-text" style="margin-top:10px">${esc(m.explanation)}</p><div class="actions" style="margin-top:13px">${btn('Editar','mistake-edit',`data-id="${m.id}"`,'quiet small')}${btn('Entender com IA','ai-from-mistake',`data-id="${m.id}"`,'quiet small')}${btn('Criar cartão','card-from-mistake',`data-id="${m.id}"`,'secondary small')}${btn(m.resolved?'Reabrir':'Marcar resolvido','mistake-resolve',`data-id="${m.id}"`,'quiet small')}</div></div>`).join(''):empty('O erro pode virar aprendizado','Anote o conceito que confundiu você e como chegar à resposta correta.',btn('Anotar dificuldade','mistake-new'))}</section><aside class="stack"><section class="panel">${panelHead('Desempenho por matéria','Histórico de questões registrado')} ${e.subjects.filter(s=>!s.archived).map(s=>{const st=topicStats(s.id,null);return `<div class="goal-row"><div class="spread"><span>${esc(s.name)}</span><strong>${st.q?st.accuracy+'%':'Sem dados'}</strong></div>${progress(st.c,st.q)}<small>${st.q} questões · ${st.q-st.c} erros</small></div>`}).join('')}</section><div class="note">Não precisa registrar o mesmo bloco em duas telas. Um registro com tempo e questões conta uma única vez nas estatísticas.</div></aside></div>`}
function viewReviews(){const dues=dueTopics(),upcoming=allTopics().filter(x=>x.t.nextReview&&x.t.nextReview>today()&&!x.s.archived).sort((a,b)=>a.t.nextReview.localeCompare(b.t.nextReview));return heading('Lembrar é parte do plano.','Retome assuntos estudados e tente recuperar o conteúdo antes de reler.',btn('Praticar cartões','navigate','data-route="cartoes"','primary'))+`<div class="grid two"><section class="panel">${panelHead('Revisões disponíveis',`${dues.length} assuntos para retomar`)}${dues.map(x=>`<div class="row"><div class="row-time">${Math.max(0,diffDays(x.t.nextReview,today()))}d<br><small>atraso</small></div><div class="row-main"><h3>${esc(x.t.name)}</h3><p>${esc(x.s.name)} · etapa ${x.t.reviewCount||0} de revisão</p></div>${btn('Revisar','review-topic',`data-sid="${x.s.id}" data-tid="${x.t.id}"`,'secondary small')}</div>`).join('')||empty('Revisões em dia','Ao registrar um estudo, ative a revisão do assunto. Ele aparecerá aqui na data escolhida.')}<div class="separation"></div>${panelHead('Próximas revisões')} ${upcoming.slice(0,15).map(x=>`<div class="row"><div class="row-main"><h3>${esc(x.t.name)}</h3><p>${esc(x.s.name)}</p></div><span class="tag">${dateLabel(x.t.nextReview)}</span></div>`).join('')||'<p style="font-size:.83rem">Nenhuma revisão futura agendada.</p>'}</section><aside class="stack"><section class="panel">${panelHead('Ajuste ao que você lembra')}<div class="insight"><h3>Preciso retomar</h3><p>Reagende para amanhã e releia a explicação depois de tentar responder.</p></div><div class="insight"><h3>Lembro com esforço</h3><p>Volte em 3 dias e teste o conteúdo novamente.</p></div><div class="insight"><h3>Lembro bem</h3><p>Amplie o intervalo conforme suas revisões: 7, 14, 30 e 60 dias.</p></div></section><div class="note">Os intervalos são regras simples de organização. Seu resultado na revisão decide a próxima data.</div></aside></div>`}
function viewCards(){const e=exam(),queue=cardMode==='all'?e.cards.filter(c=>!c.suspended):dueCards();let card=queue.find(c=>c.id===reviewCardId)||queue[0];reviewCardId=card?.id||null;return heading('Teste sua memória.','Responda mentalmente antes de revelar. Depois, avalie o que conseguiu recuperar.',btn('Novo cartão','card-new','','primary'))+`<div class="filters"><div class="segmented"><button class="${cardMode==='review'?'active':''}" data-action="card-mode" data-value="review">Revisão de hoje (${dueCards().length})</button><button class="${cardMode==='all'?'active':''}" data-action="card-mode" data-value="all">Todos (${e.cards.filter(c=>!c.suspended).length})</button></div></div><div class="grid two"><section>${card?`<div class="spread" style="margin-bottom:15px"><small>${esc(subjectName(card.subjectId))} · ${esc(topicName(card.subjectId,card.topicId))}</small>${btn('Editar','card-edit',`data-id="${card.id}"`,'quiet small')}</div><button class="flashcard ${cardAnswer?'answer':''}" data-action="card-flip"><small>${cardAnswer?'Resposta':'Pergunta'}</small><h2>${esc(cardAnswer?card.back:card.front)}</h2><small style="margin:25px 0 0">${cardAnswer?'Avalie sua lembrança abaixo.':'Clique ou use espaço para revelar.'}</small></button>${cardAnswer?`<div class="ratings">${[['again','Não lembrei','1 dia'],['hard','Com dificuldade','3 dias'],['good','Lembrei bem','Intervalo gradual'],['easy','Foi fácil','Intervalo maior']].map(([v,l,h])=>btn(`${l}<span class="rating-help">${h}</span>`,'card-rate',`data-value="${v}" data-id="${card.id}"`)).join('')}</div>`:''}<p style="font-size:.8rem;margin-top:20px">${queue.length} cartões nesta fila · Próxima revisão deste cartão: ${dateLabel(card.due)}</p>`: `<section class="panel">${empty(e.cards.length?'Você terminou a fila de hoje.':'Uma pergunta de cada vez.',e.cards.length?'Volte na próxima data ou explore todos os cartões.':'Crie perguntas curtas a partir dos assuntos e dos seus erros.',btn('Criar cartão','card-new'))}</section>`}</section><aside class="stack"><section class="panel">${panelHead('Cartões que ajudam')}<div class="insight"><h3>Uma ideia por cartão</h3><p>Prefira perguntas específicas a resumos longos.</p></div><div class="insight"><h3>Explique, não reconheça</h3><p>Tente formular a resposta antes de abrir o verso.</p></div><div class="insight"><h3>Seja honesto na avaliação</h3><p>Não lembrar faz parte. Use o resultado para ajustar a próxima prática.</p></div></section>${e.cards.length?`<section class="panel">${panelHead('Gerenciar cartões')}<div style="max-height:280px;overflow:auto">${e.cards.map(c=>`<div class="row"><div class="row-main"><h3>${esc(c.front.slice(0,80))}</h3><p>${c.suspended?'Suspenso':dateLabel(c.due)}</p></div>${btn('Editar','card-edit',`data-id="${c.id}"`,'quiet small')}</div>`).join('')}</div></section>`:''}</aside></div>`}
function viewAnalytics(){const e=exam(),sessions=periodSessions(analyticsDays),st=stats(sessions),days=new Set(sessions.map(s=>s.date)).size,start=addDays(today(),1-analyticsDays),prev=stats(e.sessions.filter(s=>s.date>=addDays(start,-analyticsDays)&&s.date<start)),recs=recommendations(),buckets=Array.from({length:analyticsDays<=14?analyticsDays:10},(_,i)=>{const span=analyticsDays<=14?1:Math.ceil(analyticsDays/10),a=addDays(start,i*span),b=addDays(start,Math.min(analyticsDays-1,(i+1)*span-1));return {date:a,...stats(sessions.filter(s=>s.date>=a&&s.date<=b))}}).filter(x=>x.date<=today()),max=Math.max(30,...buckets.map(x=>x.m));return heading('Veja o que está mudando.','Compare esforço, cobertura e resultados sem confundir uma medida com a outra.',btn('Exportar registros','csv'))+`<div class="filters"><div class="segmented">${[7,14,30,90].map(n=>`<button class="${analyticsDays===n?'active':''}" data-action="analytics-range" data-days="${n}">${n} dias</button>`).join('')}</div><small>${dateLabel(start)} até ${dateLabel(today())}</small></div><div class="metrics">${metric('Tempo estudado',minutesLabel(st.m),`${st.m>=prev.m?'+':''}${minutesLabel(st.m-prev.m)} vs. período anterior`)}${metric('Questões resolvidas',st.q,`${st.q-prev.q>=0?'+':''}${st.q-prev.q} vs. período anterior`)}${metric('Acerto no período',st.accuracy===null?'Sem dados':st.accuracy+'%',prev.accuracy===null?'Sem referência anterior':`${st.accuracy===null?'Sem dados atuais':(st.accuracy-prev.accuracy>=0?'+':'')+(st.accuracy-prev.accuracy)+' pontos percentuais'}`)}${metric('Dias ativos',`${days} <span>/ ${analyticsDays}</span>`,`${Math.round(days/analyticsDays*100)}% dos dias com estudo`)}</div><div class="grid two"><section class="panel">${panelHead('Tempo de estudo','Minutos por dia ou grupo de dias')}<div class="chart" role="img" aria-label="Gráfico de minutos estudados no período">${buckets.map(x=>`<div class="chart-col" title="${dateLabel(x.date)}: ${minutesLabel(x.m)}"><span class="chart-value">${x.m||''}</span><div class="chart-bar" style="height:${x.m/max*155}px"></div><small>${dateLabel(x.date)}</small></div>`).join('')}</div><div class="screen-reader">${buckets.map(x=>`${dateLabel(x.date)}: ${x.m} minutos`).join('; ')}</div></section><section class="panel">${panelHead('Constância nos últimos 56 dias','Cada quadrado representa um dia de estudo')}<div class="heatmap">${Array.from({length:56},(_,i)=>{const d=addDays(today(),i-55),st=stats(e.sessions.filter(s=>s.date===d)),level=st.m>=90?3:st.m>=30?2:st.m>0||st.q>0?1:0;return `<div class="heat-cell" data-level="${level}" role="img" aria-label="${dateLabel(d)}: ${st.m} minutos e ${st.q} questões" title="${dateLabel(d)}: ${minutesLabel(st.m)}, ${st.q} questões"></div>`}).join('')}</div><small>Mais intensidade indica mais tempo. Questões sem tempo também contam como atividade.</small></section><section class="panel">${panelHead('Resultado por matéria','O tamanho da amostra aparece junto ao percentual')}<div class="table-wrap"><table><thead><tr><th>Matéria</th><th>Tempo</th><th>Questões</th><th>Acerto</th></tr></thead><tbody>${e.subjects.map(s=>{const st=stats(sessions.filter(x=>x.subjectId===s.id));return `<tr><td>${esc(s.name)}</td><td>${minutesLabel(st.m)}</td><td>${st.q}</td><td>${st.accuracy===null?'Sem dados':st.accuracy+'%'}${st.q>0&&st.q<10?'<small>Amostra pequena</small>':''}</td></tr>`}).join('')}</tbody></table></div></section><section class="panel">${panelHead('Leituras para a próxima semana')}<div class="insight"><h3>${st.q<20?'Construa uma base de questões':'Compare assuntos, não apenas horas'}</h3><p>${st.q<20?'Ainda há poucas questões no período. Registre mais resultados antes de concluir que um assunto está dominado.':'Procure assuntos com mais erros e uma quantidade suficiente de questões para escolher seu próximo reforço.'}</p></div>${recs.slice(0,3).map(x=>`<div class="insight"><h3>${esc(x.t.name)}</h3><p>${esc(reason(x.s,x.t))}.</p></div>`).join('')}</section></div>`}
function viewMocks(){const e=exam(),mocks=e.mockExams||[];return heading('Treine o dia da prova.','Registre um simulado por matéria, confira o tempo e escolha seu próximo reforço.',btn('Registrar simulado','mock-new','','primary'))+`<div class="grid two"><section class="stack">${mocks.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(m=>{const records=e.sessions.filter(s=>m.sessionIds.includes(s.id)),st=stats(records),score=st.c-(st.q-st.c)*m.penalty;return `<article class="panel">${panelHead(esc(m.name),`${dateLabel(m.date,true)} · ${minutesLabel(st.m)} usados${m.timeLimit?' de '+minutesLabel(m.timeLimit):''}`,btn('Excluir','mock-delete',`data-id="${m.id}"`,'quiet small'))}<div class="inline-stats"><strong>${st.q} questões</strong><strong>${st.accuracy===null?'Sem dados':st.accuracy+'% de acerto'}</strong><strong>${score.toLocaleString('pt-BR')} pontos líquidos</strong></div><div style="margin:20px 0">${progress(st.c,st.q)}</div>${records.map(s=>`<div class="row"><div class="row-main"><h3>${esc(subjectName(s.subjectId))}</h3><p>${s.correct}/${s.qty} acertos · ${minutesLabel(s.minutes)}${s.notes?' · '+esc(s.notes):''}</p></div>${btn('Corrigir','session-edit',`data-id="${s.id}"`,'quiet small')}</div>`).join('')}<p class="form-help">Pontuação: 1 por acerto${m.penalty?', menos '+m.penalty.toLocaleString('pt-BR')+' por erro':', sem desconto por erro'}. Questões em branco não entram neste cálculo.</p></article>`}).join('')||`<section class="panel">${empty('Pratique sob condições reais','Use um simulado de sua escolha e registre tempo e resultado por matéria.',btn('Registrar primeiro simulado','mock-new'))}</section>`}</section><aside class="stack"><section class="panel">${panelHead('Depois do simulado')}<div class="insight"><h3>Confira o tempo por matéria</h3><p>Uma matéria com bom acerto e muito tempo pode precisar de treino de ritmo.</p></div><div class="insight"><h3>Separe os tipos de erro</h3><p>Registre no caderno o que foi falta de conteúdo, interpretação ou atenção.</p></div><div class="insight"><h3>Replaneje o reforço</h3><p>Os resultados entram no desempenho recente e influenciam as sugestões de estudo.</p></div></section><div class="note">Cada matéria vira um registro no histórico. O simulado reúne esses registros e conta o tempo uma única vez.</div></aside></div>`}
function viewLibrary(){return heading('Tudo o que apoia seu estudo.','Guarde links e notas por assunto. Use suas próprias palavras para organizar o conteúdo.',btn('Adicionar material','resource-new','','primary'))+`<div class="grid three">${exam().resources.map(r=>`<article class="panel resource"><div>${tag(r.kind)}<h2 style="margin-top:12px">${esc(r.title)}</h2><small>${esc(subjectName(r.subjectId))} · ${esc(topicName(r.subjectId,r.topicId))}</small></div><p>${esc(r.notes)}</p><div class="actions">${safeURL(r.url)?`<a class="primary small" href="${esc(safeURL(r.url))}" target="_blank" rel="noopener noreferrer">Abrir material</a>`:''}${btn('Editar','resource-edit',`data-id="${r.id}"`,'quiet small')}${btn('Criar cartão','card-from-resource',`data-id="${r.id}"`,'quiet small')}</div></article>`).join('')}</div>${!exam().resources.length?`<section class="panel">${empty('Seu material, no lugar certo','Adicione uma aula, um PDF online, um resumo ou uma nota de estudo.',btn('Adicionar material','resource-new'))}</section>`:''}`}
function viewHistory(){const e=exam(),list=e.sessions.filter(s=>(historyFilter==='all'||(historyFilter==='questions'?s.qty>0:s.type===historyFilter))&&(!sessionFilter||`${subjectName(s.subjectId)} ${topicName(s.subjectId,s.topicId)} ${s.notes}`.toLowerCase().includes(sessionFilter.toLowerCase()))).sort((a,b)=>b.date.localeCompare(a.date)||b.created.localeCompare(a.created));return heading('Cada sessão faz parte do caminho.','Edite seus registros, corrija resultados e acompanhe o que foi realizado.',btn('Exportar CSV','csv')+btn('Registrar estudo','session','','primary'))+`<div class="filters"><input id="history-search" value="${esc(sessionFilter)}" placeholder="Buscar matéria, assunto ou anotação" aria-label="Buscar registros"><select id="history-type" aria-label="Tipo de registro"><option value="all">Todos os registros</option>${['questions','Teoria','Revisão','Questões','Simulado','Lei seca','Videoaula','Resumo'].map(x=>`<option value="${x}" ${x===historyFilter?'selected':''}>${x==='questions'?'Com questões':x}</option>`).join('')}</select></div><section class="panel"><div id="history-list">${historyList(list)}</div></section>`}
function historyList(list){return list.length?`<div class="table-wrap"><table><thead><tr><th>Data e assunto</th><th>Tipo</th><th>Tempo real</th><th>Questões</th><th>Ações</th></tr></thead><tbody>${list.map(s=>`<tr><td>${dateLabel(s.date,true)}<small>${esc(subjectName(s.subjectId))} · ${esc(topicName(s.subjectId,s.topicId))}</small>${s.notes?`<small class="detail-text">${esc(s.notes)}</small>`:''}</td><td>${esc(s.type)}</td><td>${minutesLabel(s.minutes)}</td><td>${s.qty?`${s.correct}/${s.qty}<small>${Math.round(s.correct/s.qty*100)}% de acerto${s.board?' · '+esc(s.board):''}</small>`:'Sem questões'}</td><td>${btn('Editar','session-edit',`data-id="${s.id}"`,'quiet small')}</td></tr>`).join('')}</tbody></table></div>`:empty('Nenhum registro encontrado','Suas sessões e questões aparecerão aqui depois de registradas.')}
function viewSettings(){const e=exam();return heading('Seu ritmo, suas escolhas.','Ajuste sua preparação e mantenha seus dados com você.',btn('Nova preparação','exam-new','','primary'))+`<div class="grid equal"><section class="panel">${panelHead('Preferências')}<form id="preferences-form"><label>Como quer ser chamado?<input name="name" value="${esc(db.name)}" maxlength="80" required></label><label style="margin-top:15px">Aparência<select name="theme"><option value="light" ${db.theme==='light'?'selected':''}>Clara</option><option value="dark" ${db.theme==='dark'?'selected':''}>Escura</option></select></label><div class="actions" style="margin-top:20px"><button class="primary small">Salvar preferências</button></div></form></section><section class="panel">${panelHead('Seus dados ficam com você')}<p style="font-size:.84rem;margin-bottom:18px">O Norte funciona offline e salva no navegador deste aparelho. A sincronização entre dispositivos é feita por exportação e importação de backup.</p><div class="actions">${btn('Exportar backup','export','','primary')}${btn('Importar backup','import')}</div><p class="form-help">Aceita o backup do Norte e o JSON exportado pelo seu painel anterior. A importação aparece para revisão antes de ser aplicada.</p>${btn('Conhecer exemplo em outra preparação','demo','','quiet small')}</section>${e?`<section class="panel">${panelHead('Sua preparação')}<form id="exam-settings" class="form-grid"><label class="full">Nome da preparação<input name="name" value="${esc(e.name)}" required maxlength="120"></label><label>${studyKind()==='concurso'?'Cargo':'Referência do objetivo (opcional)'}<input name="position" value="${esc(e.position)}" maxlength="150"></label><label>${studyKind()==='concurso'?'Banca':'Instituição ou referência (opcional)'}<input name="board" value="${esc(e.board)}" maxlength="120"></label><label class="full">${studyKinds[studyKind()].date}<input name="date" type="date" value="${e.date}"></label><label>Meta diária de minutos<input name="dailyMinutes" type="number" min="5" max="1440" value="${e.dailyMinutes}" required></label><label>Meta diária de questões<input name="dailyQuestions" type="number" min="1" max="5000" value="${e.dailyQuestions}" required></label><label>Meta semanal de minutos<input name="weeklyMinutes" type="number" min="5" max="10080" value="${e.weeklyMinutes}" required></label><label>Referência de acerto (%)<input name="targetAccuracy" type="number" min="1" max="100" value="${e.targetAccuracy}" required></label><label>Duração dos blocos<select name="blockMinutes">${[25,30,40,45,50].map(n=>`<option value="${n}" ${e.blockMinutes===n?'selected':''}>${n} minutos</option>`).join('')}</select></label><div class="full"><button class="primary small">Salvar preparação</button></div></form></section><section class="panel">${panelHead('Disponibilidade semanal','Sem sobrecarregar os seus dias')}<form id="availability-form">${availabilityFields(e)}<div class="actions" style="margin-top:18px"><button class="primary small">Salvar horários</button></div><p class="form-help">Os horários devem começar e terminar no mesmo dia. Desative os dias de descanso.</p></form></section>`:''}<section class="panel">${panelHead('Como usar bem o Norte')}<div class="insight"><h3>1. Personalize o edital</h3><p>Cadastre os tópicos e ajuste os pesos à importância deles na sua prova.</p></div><div class="insight"><h3>2. Planeje e execute</h3><p>Gere a semana, escolha uma tarefa e registre o resultado real.</p></div><div class="insight"><h3>3. Revise e ajuste</h3><p>Retome dificuldades, pratique cartões e acompanhe a evolução por assunto.</p></div></section><section class="panel">${panelHead('Portabilidade e recuperação')}<p style="font-size:.84rem;margin-bottom:15px">Baixe um backup regularmente, especialmente antes de limpar os dados do navegador ou trocar de aparelho. Preparações são separadas dentro deste aplicativo.</p>${e?btn('Excluir esta preparação','exam-delete','','danger'):''}<p class="form-help">A exclusão exige confirmação e oferece a opção de desfazer imediatamente.</p></section></div>`}
function availabilityFields(e){return e.availability.map(a=>`<div class="availability"><label><input type="checkbox" name="enabled-${a.day}" ${a.enabled?'checked':''}>${['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'][a.day]}</label><input type="time" name="start-${a.day}" value="${a.start}" aria-label="Início de ${['domingo','segunda','terça','quarta','quinta','sexta','sábado'][a.day]}" required><input type="time" name="end-${a.day}" value="${a.end}" aria-label="Fim de ${['domingo','segunda','terça','quarta','quinta','sexta','sábado'][a.day]}" required><span class="day-total muted">${minutesLabel(Math.max(0,timeMin(a.end)-timeMin(a.start)))}</span></div>`).join('')}
function modal(title,subtitle,body,submit='Salvar',handler=null,extra=''){
 const dlg=$('#modal');if(dlg.open)dlg.close();
 dlg.innerHTML=`<div class="dialog-header"><div><h2 id="modal-title">${title}</h2><p>${subtitle}</p></div>${btn('Fechar','modal-close','','quiet small')}</div>${handler?'<form id="modal-form">':''}${body}${handler?`<div class="form-error" id="form-error" role="alert"></div><div class="dialog-actions">${extra}${btn('Cancelar','modal-close')}<button class="primary" type="submit">${submit}</button></div></form>`:extra}`;
 dlg.showModal();
 if(handler)$('#modal-form').onsubmit=event=>{event.preventDefault();const form=event.currentTarget;try{handler(Object.fromEntries(new FormData(form)),form)}catch(e){$('#form-error').textContent=e.message}};
 $('#form-subject')?.addEventListener('change',event=>{$('#form-topic').innerHTML=topicOptions(event.target.value)});
}
function closeModal(){$('#modal').close()}
function openExam(){modal('Sua próxima conquista','Comece com seu objetivo. Depois, personalize o edital.',`<div class="form-grid"><label class="full">Nome da preparação<input name="name" required maxlength="120" placeholder="Ex.: Concurso administrativo"></label><label>Cargo<input name="position" maxlength="150" placeholder="Opcional"></label><label>Banca<input name="board" maxlength="120" placeholder="Opcional"></label><label class="full">Data da prova<input type="date" name="date"></label><label class="full">Matérias iniciais<select name="base"><option value="standard">Base geral para personalizar</option><option value="empty">Começar com edital vazio</option></select></label><p class="full form-help">A base é um exemplo organizacional. Confira cada assunto no seu edital.</p></div>`,'Criar preparação',d=>{const e=newExam(d.name.trim());if(!e.name)throw Error('Informe um nome.');Object.assign(e,{position:d.position.trim(),board:d.board.trim(),date:d.date});if(d.base==='standard')e.subjects=baseSubjects();db.exams.push(e);db.activeExam=e.id;closeModal();go('hoje');commit('Preparação criada. Personalize o edital.');})}
function baseSubjects(){return [['Língua Portuguesa',5,['Interpretação de textos','Concordância verbal e nominal','Regência e crase','Pontuação']],['Raciocínio Lógico',4,['Proposições e conectivos','Equivalências e negações','Porcentagem e proporção']],['Direito Constitucional',4,['Princípios fundamentais','Direitos e garantias fundamentais','Organização do Estado']],['Direito Administrativo',4,['Princípios da Administração Pública','Atos administrativos','Licitações e contratos']],['Informática',3,['Sistemas operacionais','Planilhas eletrônicas','Segurança da informação']]].map(([name,weight,topics])=>({id:id(),name,weight,archived:false,topics:topics.map(name=>({id:id(),name,weight:3,stage:'new',notes:'',nextReview:null,reviewCount:0}))}))}
function openSubject(sid){const s=subject(sid);modal(s?'Editar matéria':'Adicionar matéria',studyKind()==='concurso'?'O peso representa a importância da matéria na sua prova.':'O peso representa a importância desta disciplina ou tema no seu objetivo.',`<div class="form-grid"><label class="full">Nome<input name="name" value="${esc(s?.name||'')}" required maxlength="180"></label><label>Importância (1 a 5)<input type="number" name="weight" min="1" max="5" step="1" value="${s?.weight||3}" required></label>${s?`<label class="checkbox-label"><input type="checkbox" name="archived" ${s.archived?'checked':''}>Arquivar matéria</label>`:`<label class="full">Assuntos, um por linha<textarea name="topics" rows="5" placeholder="Interpretação de textos\nConcordância verbal"></textarea></label>`}</div>`,'Salvar matéria',d=>{if(!d.name.trim()||!num(d.weight,1,5))throw Error('Informe nome e peso entre 1 e 5.');if(s)Object.assign(s,{name:d.name.trim(),weight:+d.weight,archived:d.archived==='on'});else exam().subjects.push({id:id(),name:d.name.trim(),weight:+d.weight,archived:false,topics:makeTopics(d.topics)});closeModal();commit('Matéria salva.');});}
function makeTopics(text){const names=[...new Set(text.split('\n').map(x=>x.trim()).filter(Boolean))];if(names.some(x=>x.length>250))throw Error('Use até 250 caracteres por assunto.');if(names.length>1000)throw Error('Adicione até 1.000 assuntos por vez.');return names.map(name=>({id:id(),name,weight:3,stage:'new',notes:'',nextReview:null,reviewCount:0}))}
function openTopic(sid,tid){const s=subject(sid),t=topic(sid,tid);modal(t?'Detalhes do assunto':'Adicionar assuntos',esc(s.name),t?`<div class="form-grid"><label class="full">Assunto<input name="name" value="${esc(t.name)}" required maxlength="250"></label><label>Peso (1 a 5)<input name="weight" type="number" min="1" max="5" value="${t.weight}" required></label><label>Etapa<select name="stage">${stages.map(([v,l])=>`<option value="${v}" ${v===t.stage?'selected':''}>${l}</option>`).join('')}</select></label><label class="full">Próxima revisão<input type="date" name="nextReview" value="${t.nextReview||''}"></label><label class="full">Notas do assunto<textarea name="notes" rows="5">${esc(t.notes)}</textarea></label></div>`:`<label>Assuntos, um por linha<textarea name="topics" rows="8" required placeholder="Cole os tópicos do seu edital"></textarea></label>`,'Salvar',d=>{if(t){if(!d.name.trim()||!num(d.weight,1,5))throw Error('Confira nome e peso do assunto.');Object.assign(t,{name:d.name.trim(),weight:+d.weight,stage:d.stage,nextReview:d.nextReview||null,notes:d.notes.trim()})}else{const existing=new Set(s.topics.map(t=>t.name.toLowerCase()));const added=makeTopics(d.topics).filter(t=>!existing.has(t.name.toLowerCase()));if(!added.length)throw Error('Inclua pelo menos um assunto novo.');s.topics.push(...added)}closeModal();commit('Edital atualizado.');},t?btn('Excluir assunto','topic-delete',`data-sid="${sid}" data-tid="${tid}"`,'danger small'):'')}
function sessionForm({existing=null,sid=null,tid=null,pid=null,type='Teoria',minutes=null,timer=false,review=false}={}){
 const e=exam(),p=e.plans.find(p=>p.id===pid),s=existing;sid=s?.subjectId||sid||p?.subjectId||e.subjects.find(s=>!s.archived)?.id;tid=s?.topicId||tid||p?.topicId||'';
 if(!sid){toast('Adicione uma matéria antes de registrar.');go('edital');return}
 modal(s?'Editar registro':review?'Registrar revisão':'Registrar uma sessão',s?'Corrija o registro sem duplicar seu histórico.':'Tempo e questões entram juntos no histórico.',`<div class="form-grid">${selection(sid,tid)}<label>Data<input type="date" name="date" value="${s?.date||(timer?db.timer?.date:p?.date)||today()}" max="${today()}" required></label><label>Tipo<select name="type">${['Teoria','Revisão','Questões','Simulado','Lei seca','Videoaula','Resumo'].map(v=>`<option ${v===(s?.type||p?.type||type)?'selected':''}>${v}</option>`).join('')}</select></label><label>Tempo real (minutos)<input name="minutes" type="number" min="0" max="1440" step="1" value="${s?.minutes??minutes??(p?timeMin(p.end)-timeMin(p.start):30)}" required></label><label>Banca (opcional)<input name="board" value="${esc(s?.board||e.board)}" maxlength="120"></label><label>Questões resolvidas<input name="qty" type="number" min="0" max="100000" step="1" value="${s?.qty||0}" required></label><label>Acertos<input name="correct" type="number" min="0" max="100000" step="1" value="${s?.correct||0}" required></label><label class="full">O que aprendeu ou precisa retomar?<textarea name="notes" rows="3">${esc(s?.notes||'')}</textarea></label>${review?`<label class="full">Como foi recuperar o conteúdo?<select name="reviewRating"><option value="again">Preciso retomar amanhã</option><option value="hard">Lembro com esforço, voltar em 3 dias</option><option value="good" selected>Lembro bem, ampliar o intervalo</option></select></label>`:s?'':`<label class="full checkbox-label"><input type="checkbox" name="scheduleReview" checked>Agendar revisão do assunto em 1 dia</label>`}<p class="full form-help">Se registrou este bloco em outra tela, edite o registro existente para evitar duplicidade.</p></div>`,'Salvar registro',d=>{
  if(!validDate(d.date)||d.date>today())throw Error('Use uma data válida, hoje ou anterior.');
  if(!subject(d.subjectId)||d.topicId&&!topic(d.subjectId,d.topicId))throw Error('Escolha uma matéria e um assunto válidos.');
  if(!num(d.minutes,0,1440)||!Number.isInteger(+d.minutes)||!num(d.qty,0,100000)||!Number.isInteger(+d.qty)||!num(d.correct,0,+d.qty)||!Number.isInteger(+d.correct))throw Error('Confira os números: acertos não podem superar a quantidade de questões.');
  if(+d.minutes===0&&+d.qty===0)throw Error('Informe tempo de estudo ou questões resolvidas.');
  const record={id:s?.id||id(),created:s?.created||new Date().toISOString(),date:d.date,subjectId:d.subjectId,topicId:d.topicId||null,type:d.type,minutes:+d.minutes,qty:+d.qty,correct:+d.correct,notes:d.notes.trim(),board:d.board.trim(),planId:s?.planId||pid||null,source:s?.source||(timer?'timer':p?'plan':'manual')};
  if(s)Object.assign(s,record);else e.sessions.push(record);
  if(p){p.status='done';p.sessionId=record.id}
  const t=topic(d.subjectId,d.topicId);
  if(t){if(t.stage==='new')t.stage='learning';if(review){t.reviewCount=(t.reviewCount||0)+1;t.nextReview=addDays(d.date,d.reviewRating==='again'?1:d.reviewRating==='hard'?3:[7,14,30,60][Math.min(3,t.reviewCount-1)])}else if(d.scheduleReview)t.nextReview=addDays(d.date,1)}
  if(timer)db.timer=null;closeModal();commit('Sessão registrada. Bom trabalho.');
 },s?btn('Excluir registro','session-delete',`data-id="${s.id}"`,'danger small'):'');
}
function openMistake(mid){const m=exam().mistakes.find(x=>x.id===mid),sid=m?.subjectId||exam().subjects.find(s=>!s.archived)?.id;if(!sid)return toast('Adicione uma matéria primeiro.');modal(m?'Editar dificuldade':'Anotar uma dificuldade','Registre o raciocínio para aprender com o erro.',`<div class="form-grid">${selection(sid,m?.topicId)}<label class="full">Pergunta ou dificuldade<input name="title" required value="${esc(m?.title||'')}" maxlength="400" placeholder="O que você confundiu?"></label><label class="full">Motivo<select name="category">${['Conceito','Interpretação','Memorização','Atenção','Cálculo','Outro'].map(v=>`<option ${m?.category===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="full">Explicação correta e como evitar o erro<textarea name="explanation" required rows="5">${esc(m?.explanation||'')}</textarea></label></div>`,'Salvar dificuldade',d=>{if(!d.title.trim()||!d.explanation.trim())throw Error('Preencha a dificuldade e a explicação.');const data={id:m?.id||id(),subjectId:d.subjectId,topicId:d.topicId||null,title:d.title.trim(),category:d.category,explanation:d.explanation.trim(),resolved:m?.resolved||false,date:m?.date||today()};if(m)Object.assign(m,data);else exam().mistakes.push(data);closeModal();commit('Dificuldade salva.');},m?btn('Excluir','mistake-delete',`data-id="${m.id}"`,'danger small'):'')}
function openCard(cid,prefill={}){const c=exam().cards.find(x=>x.id===cid),sid=c?.subjectId||prefill.subjectId||exam().subjects.find(s=>!s.archived)?.id;if(!sid)return toast('Adicione uma matéria primeiro.');modal(c?'Editar cartão':'Criar cartão de memória','Uma pergunta específica e uma resposta clara.',`<div class="form-grid">${selection(sid,c?.topicId||prefill.topicId)}<label class="full">Pergunta<textarea name="front" required rows="3">${esc(c?.front||prefill.front||'')}</textarea></label><label class="full">Resposta<textarea name="back" required rows="4">${esc(c?.back||prefill.back||'')}</textarea></label>${c?`<label>Próxima revisão<input type="date" name="due" value="${c.due}" required></label><label class="checkbox-label"><input type="checkbox" name="suspended" ${c.suspended?'checked':''}>Suspender cartão</label>`:''}</div>`,'Salvar cartão',d=>{if(!d.front.trim()||!d.back.trim())throw Error('Preencha a pergunta e a resposta.');const data={id:c?.id||id(),subjectId:d.subjectId,topicId:d.topicId||null,front:d.front.trim(),back:d.back.trim(),due:d.due||today(),interval:c?.interval||0,reps:c?.reps||0,suspended:d.suspended==='on'};if(c)Object.assign(c,data);else exam().cards.push(data);cardAnswer=false;closeModal();commit('Cartão salvo.');},c?btn('Excluir','card-delete',`data-id="${c.id}"`,'danger small'):'')}
function openResource(rid){const r=exam().resources.find(x=>x.id===rid),sid=r?.subjectId||exam().subjects.find(s=>!s.archived)?.id;if(!sid)return toast('Adicione uma matéria primeiro.');modal(r?'Editar material':'Adicionar material','Reúna referências e notas para seus estudos.',`<div class="form-grid">${selection(sid,r?.topicId)}<label class="full">Título<input name="title" value="${esc(r?.title||'')}" required maxlength="250"></label><label class="full">Tipo<select name="kind">${['Nota','Aula','PDF online','Legislação','Questões','Outro'].map(v=>`<option ${r?.kind===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="full">Link (opcional)<input name="url" type="url" value="${esc(r?.url||'')}" placeholder="https://"></label><label class="full">Notas e resumo<textarea name="notes" rows="6">${esc(r?.notes||'')}</textarea></label></div>`,'Salvar material',d=>{if(d.url&&!safeURL(d.url))throw Error('Use um link que comece com https:// ou http://.');if(!d.title.trim())throw Error('Informe um título.');const data={id:r?.id||id(),subjectId:d.subjectId,topicId:d.topicId||null,title:d.title.trim(),kind:d.kind,url:d.url,notes:d.notes.trim()};if(r)Object.assign(r,data);else exam().resources.push(data);closeModal();commit('Material salvo.');},r?btn('Excluir','resource-delete',`data-id="${r.id}"`,'danger small'):'')}
function openMock(){const e=exam(),subjects=e.subjects.filter(s=>!s.archived);if(!subjects.length)return toast('Adicione matérias ao edital primeiro.');modal('Registrar simulado','Informe o resultado por matéria, sem repetir uma sessão já registrada.',`<div class="form-grid"><label class="full">Nome do simulado<input name="name" maxlength="200" placeholder="Ex.: Simulado completo 01" required></label><label>Data<input name="date" type="date" value="${today()}" max="${today()}" required></label><label>Tempo máximo previsto (min)<input name="timeLimit" type="number" value="180" min="1" max="1440" required></label><label class="full">Desconto por erro<select name="penalty"><option value="0">Sem desconto</option><option value="0.5">0,5 ponto</option><option value="1">1 ponto</option></select></label></div><div class="table-wrap" style="margin-top:20px"><table><thead><tr><th>Matéria</th><th>Resolvidas</th><th>Acertos</th><th>Minutos</th></tr></thead><tbody>${subjects.map(s=>`<tr><td>${esc(s.name)}</td><td><input type="number" name="qty-${s.id}" value="0" min="0" max="100000" aria-label="Questões de ${esc(s.name)}" required></td><td><input type="number" name="correct-${s.id}" value="0" min="0" max="100000" aria-label="Acertos de ${esc(s.name)}" required></td><td><input type="number" name="minutes-${s.id}" value="0" min="0" max="1440" aria-label="Minutos de ${esc(s.name)}" required></td></tr>`).join('')}</tbody></table></div><label style="margin-top:18px">O que ajustar no próximo simulado?<textarea name="notes" rows="3"></textarea></label>`,'Salvar simulado',d=>{if(!d.name.trim()||!validDate(d.date)||d.date>today())throw Error('Confira o nome e a data.');const records=[];for(const s of subjects){const qty=+d['qty-'+s.id],correct=+d['correct-'+s.id],minutes=+d['minutes-'+s.id];if(!num(qty,0,100000)||!Number.isInteger(qty)||!num(correct,0,qty)||!Number.isInteger(correct)||!num(minutes,0,1440)||!Number.isInteger(minutes))throw Error('Confira os números de '+s.name+'.');if(qty||minutes)records.push({id:id(),date:d.date,created:new Date().toISOString(),subjectId:s.id,topicId:null,type:'Simulado',minutes,qty,correct,notes:d.notes.trim(),board:e.board,source:'mock',planId:null})}if(!records.length)throw Error('Informe o resultado de pelo menos uma matéria.');if(stats(records).m>1440)throw Error('O tempo total não pode superar 24 horas.');e.sessions.push(...records);e.mockExams??=[];e.mockExams.push({id:id(),name:d.name.trim(),date:d.date,timeLimit:+d.timeLimit,penalty:+d.penalty,sessionIds:records.map(s=>s.id)});closeModal();commit('Simulado registrado sem duplicar o tempo.');})}
function openPlan(pid){const p=exam().plans.find(x=>x.id===pid),sid=p?.subjectId||exam().subjects.find(s=>!s.archived)?.id;if(!sid)return toast('Adicione matérias e assuntos primeiro.');modal(p?'Editar atividade':'Planejar atividade','Escolha um horário e uma tarefa possível.',`<div class="form-grid">${selection(sid,p?.topicId)}<label>Data<input type="date" name="date" value="${p?.date||planDate}" required></label><label>Tipo<select name="type"><option ${p?.type==='Teoria'?'selected':''}>Teoria</option><option ${p?.type==='Revisão'?'selected':''}>Revisão</option><option ${p?.type==='Questões'?'selected':''}>Questões</option></select></label><label>Início<input type="time" name="start" value="${p?.start||'19:00'}" required></label><label>Fim<input type="time" name="end" value="${p?.end||'19:30'}" required></label><label class="full">Tarefa ou objetivo<input name="reason" value="${esc(p?.reason||'')}" maxlength="250" placeholder="Ex.: resolver 15 questões e corrigir os erros"></label>${p?`<label class="full">Estado<select name="status"><option value="planned" ${p.status==='planned'?'selected':''}>Planejada</option><option value="skipped" ${p.status==='skipped'?'selected':''}>Adiada</option></select></label>`:''}</div>`,'Salvar atividade',d=>{if(timeMin(d.end)<=timeMin(d.start))throw Error('O fim precisa ser depois do início no mesmo dia.');if(exam().plans.some(x=>x.id!==pid&&x.date===d.date&&x.status!=='skipped'&&timeMin(x.start)<timeMin(d.end)&&timeMin(x.end)>timeMin(d.start)))throw Error('Este horário se sobrepõe a uma atividade existente.');const data={id:p?.id||id(),date:d.date,start:d.start,end:d.end,subjectId:d.subjectId,topicId:d.topicId||null,type:d.type,reason:d.reason.trim(),status:d.status||'planned',sessionId:p?.sessionId||null};if(p)Object.assign(p,data);else exam().plans.push(data);planDate=d.date;closeModal();commit('Atividade salva.');},p?btn('Excluir atividade','plan-delete',`data-id="${p.id}"`,'danger small'):'')}
function openGenerator(){if(!allTopics().filter(x=>!x.s.archived).length)return toast('Adicione pelo menos um assunto no edital.');const e=exam();modal('Monte seu próximo plano','Você poderá revisar a sugestão antes de aplicá-la.',`<div class="form-grid"><label>Data inicial<input name="start" type="date" value="${planDate<today()?today():planDate}" min="${today()}" required></label><label>Período<select name="days"><option value="7">7 dias</option><option value="14">14 dias</option><option value="30">30 dias</option></select></label><label>Duração dos blocos<select name="block">${[25,30,40,45,50].map(n=>`<option value="${n}" ${e.blockMinutes===n?'selected':''}>${n} minutos</option>`).join('')}</select></label><label>Atividades existentes<select name="replace"><option value="keep">Preservar e usar horários livres</option><option value="replace">Substituir apenas as não concluídas</option></select></label><div class="full"><h3 style="margin:12px 0">Seus horários nesta geração</h3>${availabilityFields(e)}</div><p class="form-help full">Uma pausa de 5 minutos separa os novos blocos. Dias sem disponibilidade ficam livres. Registros concluídos são preservados.</p></div>`,'Ver sugestão', (d,form)=>{const availability=readAvailability(d);previewPlan=generatePlan(e,d.start,+d.days,+d.block,availability,d.replace==='replace');if(!previewPlan.length)throw Error('Não há horários livres de pelo menos 10 minutos no período.');const removed=d.replace==='replace'?e.plans.filter(p=>p.date>=d.start&&p.date<addDays(d.start,+d.days)&&p.status!=='done').length:0;modal('Seu plano está pronto',`${previewPlan.length} atividades · ${minutesLabel(previewPlan.reduce((a,p)=>a+timeMin(p.end)-timeMin(p.start),0))} · ${removed} atividades serão substituídas.`,`<div class="note">A prioridade usa dados atuais. Reavalie a semana conforme você estuda.</div><div class="preview-list">${previewPlan.map(p=>`<div class="row"><div class="row-time">${dateLabel(p.date)}<br>${p.start}</div><div class="row-main"><h3>${esc(topicName(p.subjectId,p.topicId))}</h3><p>${esc(subjectName(p.subjectId))} · ${timeMin(p.end)-timeMin(p.start)}min · ${esc(p.reason)}</p></div></div>`).join('')}</div>`,'Aplicar planejamento',()=>{snapshot();if(d.replace==='replace')e.plans=e.plans.filter(p=>p.date<d.start||p.date>=addDays(d.start,+d.days)||p.status==='done');e.plans.push(...previewPlan);e.availability=availability;e.blockMinutes=+d.block;planDate=d.start;closeModal();commit('Planejamento aplicado.',true)});})}
function readAvailability(d){return Array.from({length:7},(_,day)=>{const enabled=d['enabled-'+day]==='on',start=d['start-'+day],end=d['end-'+day];if(!/^\d\d:\d\d$/.test(start)||!/^\d\d:\d\d$/.test(end)||enabled&&timeMin(end)<=timeMin(start))throw Error('Confira os horários: o fim deve ser depois do início nos dias ativos.');return {day,enabled,start,end}})}
function generatePlan(e,start,days,block,availability,replace){
 if(!validDate(start)||start<today()||!num(days,1,30)||!num(block,10,120))throw Error('Confira a data e a duração do planejamento.');
 const ranked=recommendations(),used={},lastSubject=null;let previousSid=null;const result=[];
 for(let day=0;day<days;day++){const date=addDays(start,day);if(e.date&&date>e.date)break;const a=availability.find(x=>x.day===weekday(date));if(!a?.enabled)continue;
  let cursor=timeMin(a.start),end=timeMin(a.end);const occupied=e.plans.filter(p=>p.date===date&&p.status!=='skipped'&&(!replace||p.status==='done')).map(p=>[timeMin(p.start),timeMin(p.end)]).sort((a,b)=>a[0]-b[0]);
  while(cursor<end){const collision=occupied.find(([s,f])=>cursor>=s&&cursor<f);if(collision){cursor=collision[1];continue}const next=occupied.find(([s])=>s>cursor);const available=Math.min(end,next?.[0]??end)-cursor;if(available<10){cursor=next?next[1]:end;continue}const duration=Math.min(block,available);
   const choice=ranked.map(x=>({...x,adjusted:x.score/(1+(used[x.t.id]||0)*.9)-(x.s.id===previousSid&&ranked.some(y=>y.s.id!==previousSid)?4:0)})).sort((a,b)=>b.adjusted-a.adjusted)[0];
   result.push({id:id(),date,start:hm(cursor),end:hm(cursor+duration),subjectId:choice.s.id,topicId:choice.t.id,status:'planned',sessionId:null,type:choice.t.nextReview&&choice.t.nextReview<=date?'Revisão':'Teoria',reason:reason(choice.s,choice.t),generated:true});used[choice.t.id]=(used[choice.t.id]||0)+duration/block;previousSid=choice.s.id;cursor+=duration+5;
  }
 }
 return result;
}
let focusMode='countdown';
function timerElapsed(t=db.timer){return t?Math.max(0,t.elapsed+(t.running?(Date.now()-t.startedAt)/1000:0)):0}
function toggleTimer(){const t=db.timer;if(!t)return;if(t.running){t.elapsed=timerElapsed(t);t.running=false}else{if(t.mode==='countdown'&&t.elapsed>=t.duration){toast('Este bloco terminou. Registre para iniciar o próximo.');return}t.startedAt=Date.now();t.running=true}commit()}
function finishTimer(){const t=db.timer;if(!t)return;if(t.running){t.elapsed=timerElapsed(t);t.running=false;persist()}db.activeExam=t.examId;render();sessionForm({sid:t.subjectId,tid:t.topicId,pid:t.planId,minutes:Math.max(1,Math.round(t.elapsed/60)),timer:true})}
function confirmDialog(title,text,onConfirm,label='Confirmar'){modal(title,text,'<p class="form-help">Você poderá desfazer imediatamente após a ação.</p>',label,()=>{onConfirm();closeModal()})}
function removeItem(collection,itemId,label){confirmDialog('Excluir '+label+'?', 'Confira se você deseja remover este item.',()=>{snapshot();exam()[collection]=exam()[collection].filter(x=>x.id!==itemId);if(collection==='sessions'){exam().plans.forEach(p=>{if(p.sessionId===itemId){p.sessionId=null;p.status='planned'}});(exam().mockExams||[]).forEach(m=>m.sessionIds=m.sessionIds.filter(sid=>sid!==itemId))}if(collection==='plans')exam().sessions.forEach(s=>{if(s.planId===itemId)s.planId=null});commit('Item excluído.',true)},'Excluir')}
function go(r){if(!routes.some(x=>x[0]===r))r='hoje';route=r;if(location.hash!=='#'+r)history.replaceState(null,'','#'+r);$('.sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');render();window.scrollTo({top:0,behavior:'instant'})}
function openSearch(){modal('Encontre seu próximo passo','Busque assuntos, cartões, materiais e áreas do aplicativo.',`<input id="global-search" placeholder="O que você quer encontrar?" aria-label="Busca global" autofocus><div class="search-results" id="search-results"></div>`);$('#global-search').addEventListener('input',e=>showSearch(e.target.value));showSearch('')}
function showSearch(query){query=query.toLowerCase().trim();const results=routes.filter(([r,l])=>l.toLowerCase().includes(query)).map(([r,l])=>({title:l,sub:'Área do aplicativo',action:'navigate',extra:`data-route="${r}"`}));if(exam()&&query){allTopics().filter(x=>`${x.s.name} ${x.t.name}`.toLowerCase().includes(query)).slice(0,12).forEach(x=>results.push({title:x.t.name,sub:x.s.name,action:'topic-edit',extra:`data-sid="${x.s.id}" data-tid="${x.t.id}"`}));exam().cards.filter(c=>`${c.front} ${c.back}`.toLowerCase().includes(query)).slice(0,5).forEach(c=>results.push({title:c.front,sub:'Cartão de memória',action:'card-edit',extra:`data-id="${c.id}"`}));exam().resources.filter(r=>`${r.title} ${r.notes}`.toLowerCase().includes(query)).slice(0,5).forEach(r=>results.push({title:r.title,sub:'Biblioteca',action:'resource-edit',extra:`data-id="${r.id}"`}))}$('#search-results').innerHTML=results.slice(0,25).map(x=>`<button class="search-result" data-action="${x.action}" ${x.extra}>${esc(x.title)}<small>${esc(x.sub)}</small></button>`).join('')||'<p>Nenhum resultado encontrado.</p>'}
function download(filename,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
