function exportCSV(){if(!exam())return;const cell=v=>'"'+String(v??'').replace(/^[=+\-@\t\r]/,m=>"'"+m).replace(/"/g,'""')+'"';const rows=[['Data','Matéria','Assunto','Tipo','Minutos','Questões','Acertos','Banca','Notas'],...exam().sessions.map(s=>[s.date,subjectName(s.subjectId),topicName(s.subjectId,s.topicId),s.type,s.minutes,s.qty,s.correct,s.board,s.notes])];download(`norte-registros-${today()}.csv`,'\ufeff'+rows.map(row=>row.map(cell).join(';')).join('\r\n'),'text/csv;charset=utf-8');toast('Registros exportados.')}
function validateBackup(data){
 const fail=()=>{throw Error('O backup contém dados inválidos ou uma versão incompatível. Nenhum registro foi substituído.')};
 const str=(v,max=50000)=>typeof v==='string'&&v.length<=max;
 const list=(v,max=50000)=>Array.isArray(v)&&v.length<=max;
 const weight=v=>num(v,1,5);
 const identities=new Set();const checkId=v=>{if(!str(v,150)||!v||identities.has(v))fail();identities.add(v)};
 if(!data||data.version!==1||!str(data.name,80)||!['light','dark'].includes(data.theme)||!list(data.exams,100))fail();
 for(const e of data.exams){checkId(e.id);if(!str(e.name,120)||!e.name||!str(e.board,120)||!str(e.position,150)||(e.date&&!validDate(e.date))||!num(e.dailyMinutes,5,1440)||!num(e.dailyQuestions,1,5000)||!num(e.weeklyMinutes,5,10080)||!num(e.targetAccuracy,1,100)||!num(e.blockMinutes,10,120)||!list(e.subjects,1000)||!list(e.sessions)||!list(e.plans)||!list(e.cards)||!list(e.mistakes)||!list(e.resources)||!list(e.availability,7)||e.availability.length!==7)fail();
  if(e.learningProfile!==undefined){const p=e.learningProfile;if(!p||typeof p!=='object'||!['concurso','faculdade','escola','certificacao','livre'].includes(p.kind)||!['estudante','profissional','ambos','outro'].includes(p.role)||!str(p.course,120)||!str(p.term,60)||!['inicio','intermediario','avancado'].includes(p.level)||!['constancia','tempo','compreensao','memoria','pratica'].includes(p.challenge)||!['explicacao','cartoes','questoes'].includes(p.method))fail()}
  const sid=new Set(),tids=new Map();for(const s of e.subjects){checkId(s.id);sid.add(s.id);if(!str(s.name,180)||!s.name||!weight(s.weight)||typeof s.archived!=='boolean'||!list(s.topics,10000))fail();const set=new Set();for(const t of s.topics){checkId(t.id);set.add(t.id);if(!str(t.name,250)||!t.name||!weight(t.weight)||!stages.some(x=>x[0]===t.stage)||!str(t.notes)||t.nextReview&&!validDate(t.nextReview)||!num(t.reviewCount,0,100000))fail()}tids.set(s.id,set)}
  const reference=x=>{if(!sid.has(x.subjectId)||x.topicId&&!tids.get(x.subjectId).has(x.topicId))fail()};
  for(const s of e.sessions){checkId(s.id);reference(s);if(!validDate(s.date)||!str(s.created,50)||!str(s.type,50)||!str(s.notes)||!str(s.board,120)||!num(s.minutes,0,1440)||!Number.isInteger(s.minutes)||!num(s.qty,0,100000)||!Number.isInteger(s.qty)||!num(s.correct,0,s.qty)||!Number.isInteger(s.correct)||!str(s.source,50))fail()}
  for(const p of e.plans){checkId(p.id);reference(p);if(!validDate(p.date)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(p.start)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(p.end)||timeMin(p.end)<=timeMin(p.start)||!['planned','done','skipped'].includes(p.status)||!str(p.reason,500)||!str(p.type,50))fail()}
  for(const c of e.cards){checkId(c.id);reference(c);if(!str(c.front)||!c.front||!str(c.back)||!c.back||!validDate(c.due)||!num(c.interval,0,1000)||!num(c.reps,0,100000)||typeof c.suspended!=='boolean')fail()}
  for(const m of e.mistakes){checkId(m.id);reference(m);if(!str(m.title,400)||!str(m.explanation)||!str(m.category,50)||!validDate(m.date)||typeof m.resolved!=='boolean')fail()}
  for(const r of e.resources){checkId(r.id);reference(r);if(!str(r.title,250)||!str(r.kind,50)||!str(r.url,10000)||r.url&&!safeURL(r.url)||!str(r.notes))fail()}
  for(let i=0;i<7;i++){const a=e.availability[i];if(a.day!==i||typeof a.enabled!=='boolean'||!/^([01]\d|2[0-3]):[0-5]\d$/.test(a.start)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(a.end)||a.enabled&&timeMin(a.end)<=timeMin(a.start))fail()}
  if(e.studyTasks!==undefined&&!list(e.studyTasks,2000))fail();for(const t of e.studyTasks||[]){checkId(t.id);if(!str(t.title,200)||!t.title||!validDate(t.date)||!['Prova','Trabalho','Projeto','Revisão','Outro'].includes(t.kind)||!['open','done'].includes(t.status)||t.subjectId&&!sid.has(t.subjectId))fail()}
  const plans=new Set(e.plans.map(p=>p.id)),sessions=new Set(e.sessions.map(s=>s.id));for(const p of e.plans)if(p.sessionId&&!sessions.has(p.sessionId))fail();for(const s of e.sessions)if(s.planId&&!plans.has(s.planId))fail();
  if(e.mockExams!==undefined&&!list(e.mockExams))fail();for(const m of e.mockExams||[]){checkId(m.id);if(!str(m.name,200)||!validDate(m.date)||!num(m.timeLimit,1,1440)||!num(m.penalty,0,1)||!list(m.sessionIds,1000)||m.sessionIds.some(x=>!sessions.has(x)))fail()}
 }
 if(data.exams.length&&!data.exams.some(e=>e.id===data.activeExam)||!data.exams.length&&data.activeExam!==null)fail();
 if(data.timer){const t=data.timer,e=data.exams.find(e=>e.id===t.examId);if(!e||!e.subjects.some(s=>s.id===t.subjectId&&(!t.topicId||s.topics.some(x=>x.id===t.topicId)))||!num(t.duration,1,86400)||!num(t.elapsed,0,31536000)||!num(t.startedAt,0,Date.now()+86400000)||typeof t.running!=='boolean'||typeof t.notified!=='boolean'||!['countdown','free'].includes(t.mode)||!validDate(t.date))fail();if(t.alarm&&(typeof t.alarm.sound!=='boolean'||typeof t.alarm.fired!=='boolean'||!Number.isInteger(t.alarm.atSeconds)||!num(t.alarm.atSeconds,0,86400)))fail();for(const k of ['dockVisible','dockOnFocus'])if(t[k]!==undefined&&typeof t[k]!=='boolean')fail()}
 return true;
}
function migrateLegacy(data){
 if(!Array.isArray(data.subjects)||!Array.isArray(data.sessions)||!Array.isArray(data.questions)||!data.goals)throw Error('Arquivo não reconhecido.');
 const e=newExam('Importado do painel anterior'),subjectMap=new Map(),topicMap=new Map();
 e.subjects=data.subjects.map(s=>{const sid=id();subjectMap.set(s.id,sid);const topics=(s.topics||[]).map(t=>{const tid=id();topicMap.set(t.id,tid);return {id:tid,name:String(t.name||'Assunto'),weight:num(t.weight,1,5)?+t.weight:3,stage:'new',notes:'',nextReview:null,reviewCount:0}});return {id:sid,name:String(s.name||'Matéria'),weight:num(s.weight,1,5)?+s.weight:3,archived:false,topics}});
 const mapRef=x=>({subjectId:subjectMap.get(x.subjectId),topicId:topicMap.get(x.topicId)||null});
 e.sessions=data.sessions.map(s=>({id:id(),created:new Date().toISOString(),date:s.date,...mapRef(s),minutes:+s.minutes,qty:0,correct:0,type:String(s.type||'Teoria'),notes:String(s.notes||''),board:'',planId:null,source:'legacy'}));
 e.sessions.push(...data.questions.map(q=>({id:id(),created:new Date().toISOString(),date:q.date,...mapRef(q),minutes:q.startTime&&q.endTime?(timeMin(q.endTime)-timeMin(q.startTime)+1440)%1440:0,qty:+q.qty,correct:+q.correct,type:'Questões',notes:'Importado do painel anterior',board:String(q.banca||''),planId:null,source:'legacy'})));
 e.plans=(data.schedule||[]).filter(p=>p.status!=='Concluída').map(p=>({id:id(),date:p.date,start:p.start,end:p.end,...mapRef(p),status:p.status==='Não realizada'?'skipped':'planned',sessionId:null,type:'Teoria',reason:String(p.reason||'Importado')}));
 e.dailyMinutes=num(+data.goals.dailyHours*60,5,1440)?Math.round(+data.goals.dailyHours*60):90;e.dailyQuestions=num(data.goals.dailyQuestions,1,5000)?+data.goals.dailyQuestions:20;e.weeklyMinutes=num(+data.goals.weeklyHours*60,5,10080)?Math.round(+data.goals.weeklyHours*60):600;
 const backup=defaults();backup.exams=[e];backup.activeExam=e.id;validateBackup(backup);return e;
}
async function readImport(file){if(!file)return;if(file.size>20*1024*1024)return toast('O limite de importação é 20 MB.');try{const parsed=JSON.parse(await file.text());const legacy=parsed.version!==1;let imported;if(legacy)imported=migrateLegacy(parsed);else{validateBackup(parsed);imported=parsed}const text=legacy?`${imported.sessions.length} registros serão adicionados em uma nova preparação. Os dados atuais serão preservados. Confira possíveis tempos duplicados no histórico antigo.`:`${imported.exams.length} preparações serão importadas. O conteúdo atual deste aplicativo será substituído. Exporte um backup antes de continuar.`;modal('Confira a importação',text,`<div class="note">${legacy?'Importação do painel anterior.':'Backup Norte validado.'} Nenhuma mudança foi aplicada ainda.</div>`,'Importar dados',()=>{if(db.timer)throw Error('Conclua ou descarte a sessão de foco antes de importar.');snapshot();if(legacy){db.exams.push(imported);db.activeExam=imported.id}else{db=clone(imported);if(db.timer){db.timer.running=false;db.timer.startedAt=Date.now()}}closeModal();go('hoje');commit('Backup importado.',true)})}catch(e){toast(e.message.includes('JSON')?'Arquivo JSON inválido.':e.message)}finally{$('#import-file').value=''}}
function loadDemo(){const e=newExam('Preparação de exemplo');e.date=addDays(today(),84);e.board='Banca de exemplo';e.position='Área administrativa';e.subjects=baseSubjects();e.subjects.forEach((s,si)=>s.topics.forEach((t,ti)=>{if(ti<2)t.stage='covered';else if(ti===2)t.stage='learning';if(ti===0)t.nextReview=addDays(today(),si-2)}));for(let day=0;day<14;day++){if(day===4||day===9)continue;const s=e.subjects[day%e.subjects.length],t=s.topics[day%s.topics.length];e.sessions.push({id:id(),created:new Date().toISOString(),date:addDays(today(),-day),subjectId:s.id,topicId:t.id,type:day%3?'Questões':'Teoria',minutes:30+(day%3)*15,qty:day%3?20:0,correct:day%3?12+day%7:0,notes:day===0?'Retomar a justificativa das questões incorretas.':'',board:'Banca de exemplo',planId:null,source:'demo'})}const s=e.subjects[0],t=s.topics[1];e.cards.push({id:id(),subjectId:s.id,topicId:t.id,front:'Qual é a diferença entre concordância verbal e nominal?',back:'A verbal relaciona o verbo ao sujeito. A nominal relaciona adjetivos, artigos e outros termos aos substantivos.',due:today(),interval:0,reps:0,suspended:false});e.mistakes.push({id:id(),subjectId:s.id,topicId:t.id,title:'Confundir sujeito com o termo mais próximo do verbo',explanation:'Identifique o núcleo do sujeito antes de verificar a flexão verbal. Refaça as questões em que um termo intermediário causou confusão.',category:'Conceito',resolved:false,date:today()});e.resources.push({id:id(),subjectId:s.id,topicId:t.id,title:'Minha rotina de correção',kind:'Nota',url:'',notes:'1. Tentar responder sem consultar.\n2. Conferir a justificativa.\n3. Explicar a regra com minhas palavras.\n4. Criar um cartão se continuar difícil.'});snapshot();db.exams.push(e);db.activeExam=e.id;e.plans=generatePlan(e,today(),7,30,e.availability,false);closeModal();go('hoje');commit('Exemplo criado em uma preparação separada.',true)}
