document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b||b.disabled)return;event.preventDefault();try{const result=actions[b.dataset.action]?.(b);if(result?.catch)result.catch(e=>toast('Não foi possível concluir: '+e.message))}catch(e){toast('Não foi possível concluir: '+e.message);console.error(e)}});
document.addEventListener('change',event=>{const el=event.target;try{
 if(el.id==='exam-select'){if(db.timer)return toast('Conclua ou descarte a sessão de foco para trocar de preparação.'),render();db.activeExam=el.value;reviewCardId=null;cardAnswer=false;commit()}
 if(el.dataset.stage){const t=topic(el.dataset.sid,el.dataset.stage);t.stage=el.value;commit('Etapa atualizada.')}
 if(el.id==='topic-status'){topicStatus=el.value;$('#syllabus-list').innerHTML=syllabusList()}
 if(el.id==='plan-date'){planDate=el.value||today();render()}
 if(el.id==='focus-subject')$('#focus-topic').innerHTML=topicOptions(el.value);
 if(el.id==='focus-duration'&&!db.timer&&focusMode==='countdown')$('#timer-count').textContent=el.value+':00';
 if(el.id==='history-type'){historyFilter=el.value;render()}
 if(el.id==='import-file')readImport(el.files[0]);
}catch(e){toast(e.message)}});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='topic-search'){topicFilter=el.value;$('#syllabus-list').innerHTML=syllabusList()}if(el.id==='history-search'){sessionFilter=el.value;const pos=el.selectionStart;render();$('#history-search').focus();$('#history-search').setSelectionRange(pos,pos)}});
document.addEventListener('submit',event=>{const form=event.target;if(!['preferences-form','exam-settings','availability-form'].includes(form.id))return;event.preventDefault();try{const d=Object.fromEntries(new FormData(form));if(form.id==='preferences-form'){if(!d.name.trim())throw Error('Informe seu nome.');db.name=d.name.trim();db.theme=d.theme}if(form.id==='exam-settings'){if(!d.name.trim())throw Error('Informe o nome da preparação.');const e=exam();for(const [key,min,max] of [['dailyMinutes',5,1440],['dailyQuestions',1,5000],['weeklyMinutes',5,10080],['targetAccuracy',1,100],['blockMinutes',10,120]]){if(!num(d[key],min,max))throw Error('Confira as metas.');e[key]=+d[key]}Object.assign(e,{name:d.name.trim(),board:d.board.trim(),position:d.position.trim(),date:d.date})}if(form.id==='availability-form')exam().availability=readAvailability(d);commit('Preferências salvas.')}catch(e){toast(e.message)}});
